    for(let i=0;i<=8;i++){R(27+i-1,26-Math.round(i*1.5),1,1,"#7a4a2a");R(27+i-1,27-Math.round(i*1.5),1,1,OUT)}
    const by=31+(anim?(Math.sin(t/420)>0.4?1:0):0);
