  if(e==="dingin"){tc.fillStyle="rgba(110,160,255,.28)";tc.fillRect(0,0,40,42)}
  else if(e==="hangat"||pose==="lentera"){tc.fillStyle="rgba(255,170,90,.12)";tc.fillRect(0,0,40,42)}
  tc.globalCompositeOperation="source-over";
