 cepol:{n:"Cepol dua",g:"f",x:1,seg:[...RND,...BANG,...SLN(-2,3,3,8),...SLN(-2,3,23,28)],extra:()=>{R(5,4,3,1,"#ff8fa3");R(24,4,3,1,"#ff8fa3")}}
