function drawHair(H,style){
  const m=new Map();
  const set=(x,y,c)=>m.set(x+","+y,c);
  const has=(x,y)=>m.has(x+","+y);
  (HAIR_STYLES[style]||HAIR_STYLES.messy).seg.forEach(([y,x0,x1])=>{for(let x=x0;x<=x1;x++)set(x,y,H.c)});
  // bayangan: tepi bawah poni/helai & tepi luar samping
  const cells=[...m.keys()].map(k=>k.split(",").map(Number));
  cells.forEach(([x,y])=>{
    if(y>=10&&!has(x,y+1))set(x,y,H.d);
  });
  // kilau melengkung (angel ring)
  const hl=(x0,x1,y)=>{for(let x=x0;x<=x1;x++)if(has(x,y))set(x,y,H.h)};
  hl(12,14,3);hl(17,19,3);hl(9,11,4);hl(20,22,4);hl(7,8,5);hl(23,24,5);
  // helai halus
  [[10,6],[10,7],[11,8],[19,6],[19,7],[20,8],[14,9],[17,10]].forEach(([x,y])=>{if(has(x,y)&&m.get(x+","+y)===H.c)set(x,y,H.d)});
  // outline
  const out=new Set();
  m.forEach((_,k)=>{const [x,y]=k.split(",").map(Number);[[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy])=>{const kk=(x+dx)+","+(y+dy);if(!m.has(kk))out.add(kk)})});
  out.forEach(k=>{const [x,y]=k.split(",").map(Number);R(x,y,1,1,OUT)});
  m.forEach((c,k)=>{const [x,y]=k.split(",").map(Number);R(x,y,1,1,c)});
}

