function render(ctx,st,t,anim){
  ctx.clearRect(0,0,40,42);
  ctx.imageSmoothingEnabled=false;
  const {headDY}=drawChar(st,t,anim);
  /* volChar dimatikan: sprite bersih tanpa pita bayangan, seperti versi lama */
  // lantern glow
  if(st.pose==="lentera"){
    const fl=anim?(Math.sin(t/180)>0.3?1:0):0;
    C=ctx;DY=0;SX=0;
    circleGlow(23,31,9+fl,"#ffcf6b",.12);circleGlow(23,31,6+fl,"#ffe39a",.16);
  }
  ctx.drawImage(tmp,0,0);
  C=ctx;DY=0;SX=0;
  const e=st.expr, f=t/1000;
  const wave=(i)=>anim?Math.sin(f*2+i)*1:0;
  if(e==="mengantuk"&&!(anim&&T.dz===1&&T.dzb)){
    const k=anim?(Math.floor(f*1.2)%3):2;
    if(k>=0)zz(26,8-(anim?Math.floor((f*2)%2):0),"#8fa3ff");
    if(k>=1)zz(29,4,"#b8c6ff");
    if(k>=2)zz(31,0,"#dfe6ff");
  }
  if(e==="senang"){
    const s=anim?Math.floor(f*3)%2:0;
    [[3,6],[29,9],[28,16]].forEach(([x,y],i)=>{if((i+s)%2===0)pat(x,y,[".X.","XXX",".X."],"#ffe066");else R(x+1,y+1,1,1,"#ffe066")});
  }
  if(e==="takut"){
    const d=anim?Math.floor(f*3)%3:0;
    R(25,12+d,2,3,"#8fd3ff");R(25,12+d,1,1,"#fff");
    R(2,10,1,3,"#7a6aa0");R(30,12,1,3,"#7a6aa0");
    if(anim&&Math.floor(f*4)%2){R(1,16,1,2,"#7a6aa0");R(31,8,1,2,"#7a6aa0")}
  }
  if(e==="tersipu"){
    const y=anim?Math.floor((f*3)%4):0;
    pat(26,6-y,["XX.XX","XXXXX",".XXX.","..X.."],"#ff6f8f");
    if(!anim)pat(3,5,["XX.XX","XXXXX",".XXX.","..X.."],"#ffa0b4");
  }
  if(e==="berpikir"){
    const dots=anim?(Math.floor(f*1.5)%4):3;
    B(24,2,9,5,"#fff");
    for(let i=0;i<3;i++)if(i<dots)R(26+i*2,4,1,1,OUT);
    R(23,8,1,1,"#fff");R(22,9,1,1,"#fff");
  }
  if(e==="dingin"){
    const p=anim?Math.floor(f*3)%4:1;
    [[0,0],[1,-1],[2,-1],[3,-2]].forEach(([dx,dy],i)=>{if(i<=p)R(4-dx*2,22+dy,2,1,"rgba(255,255,255,.9)")});
    R(2,12,1,1,"#bfe3ff");R(30,9,1,1,"#bfe3ff");R(28,18,1,1,"#bfe3ff");
  }
  if(e==="hangat"){
    const s=anim?Math.floor(f*2)%2:0;
    [[3,10],[28,8],[29,18]].forEach(([x,y],i)=>{R(x,y-(s&&i%2?1:0),1,1,"#ffb86b");R(x-1,y+1-(s&&i%2?1:0),3,1,"rgba(255,184,107,.6)")});
    pat(27,2-s,["XX.XX","XXXXX",".XXX.","..X.."],"#ff9a6a");
  }
}
