var SPP=0;function isListen(){return (mix.on||SPP)&&!isMute()&&T.sl<=0&&!ch.lie&&(fishL()||(!T.fl&&!T.boat&&(((ch.sit==='kursi'||ch.sit==='bangku')&&ch.sb>.9)||!!T.afk)))}
