 if(out){
  if(T.boat){const b=T.boat;tz=T.fl?1.5:1.35;tx=b.x;ty=b.y-30;k=1-Math.exp(-dt/170);auto=1}
  else if(T.fl){tz=1.45;tx=ch.x;ty=ch.y-40;auto=1}
  CAM.a+=(tz-CAM.a)*k;CAM.cx+=(tx-CAM.cx)*k;CAM.cy+=(ty-CAM.cy)*k;
  if(Math.abs(CAM.a-1)<.002&&tz===1)CAM.a=1;
 }else{CAM.a=1;CAM.cx=W/2;CAM.cy=H/2}
 /* zoom pemain: pegas teredam sedikit (ada lenting halus di ujung) */
