 /* mode goyang: nilai k halus 0..1 supaya perpindahan mode tidak melompat */
 const tk=CS.m==='goyang'?1:0;CS.k+=(tk-CS.k)*(1-Math.exp(-dt/450));if(tk===0&&CS.k<.002)CS.k=0;
 const Z=Math.min(4.5,Math.max(CAM.a*UZ.v,1+.07*CS.k)),vw=W/Z,vh=H/Z,m=32*CS.k/Z;
 const cc=(c,len,h)=>{const lo=h+m,hi=len-h-m;return lo>hi?len/2:cl(c,lo,hi)};
 /* geser: pusat kamera dijepit supaya tepi layar tidak keluar dari batas map */
 PAN.on=$('w').classList.contains('ph');if(!PAN.on)PAN.tx=PAN.ty=0;
 const rg=(len,h)=>{const lo=h+m,hi=len-h-m;return lo>hi?[len/2,len/2]:[lo,hi]},rx=rg(W,vw/2),ry=rg(H,vh/2);
 PAN.tx=cl(cx+PAN.tx,rx[0],rx[1])-cx;PAN.ty=cl(cy+PAN.ty,ry[0],ry[1])-cy;
 const kp=1-Math.exp(-dt/(PAN.drag?50:150));PAN.x+=(PAN.tx-PAN.x)*kp;PAN.y+=(PAN.ty-PAN.y)*kp;
 if(Math.abs(PAN.tx-PAN.x)<.05)PAN.x=PAN.tx;if(Math.abs(PAN.ty-PAN.y)<.05)PAN.y=PAN.ty;
 CAM.z=Z;CAM.x=cc(cx+PAN.x,W,vw/2)-vw/2;CAM.y=cc(cy+PAN.y,H,vh/2)-vh/2;
 if(CS.k<=0){CAM.dx=CAM.dy=CAM.r=0;CAM.bz=1;return}
 /* goyangan ala rekam pakai tangan: tiga gelombang lambat + napas + langkah kaki + ombak perahu */
