 const pt=new Map();let pd=0,pz=1,mx=0,my=0,g0=null;const isPh=()=>$('w').classList.contains('ph');
 const dist=()=>{const a=[...pt.values()];return a.length<2?0:Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1])};
 const mid=()=>{const a=[...pt.values()],n=a.length||1;return[a.reduce((s,p)=>s+p[0],0)/n,a.reduce((s,p)=>s+p[1],0)/n]};
 /* satu jari / mouse: geser kamera. dua jari: cubit zoom + geser. ketukan singkat tetap jadi ketukan biasa */
