const PHOME=[420,775];
/* area aktif: dalam / luar / bukit */
const SCA=()=>S.kd?'kedai':S.bk?'bukit':S.scene;
const BKSC=y=>3.2+cl((y-606)/324,0,1)*.6;
const PKM=y=>S.kd?2.5:S.bk?(2.6+cl((y-590)/340,0,1)*1.2)/4:(S.scene==='luar'?1:1.5);
/* tidur pet: di kursi goyang, bukan di lantai */
const PB={u:0,want:0},PCH={ap:[850,665]},RUG=[370,765],BSX=86,BSY=-128;
function pbFree(){if(ch.sit==='kursi'||(ch.sb>0&&ch.sn==='kursi'))return false;const sp=INS.find(a=>a[0]==='kursi');if(ch.act&&Math.abs(ch.tx-sp[5])<2&&Math.abs(ch.ty-sp[6])<2)return false;if(S.fr&&S.fr.sc==='dalam'&&(FR.seat==='kursi'||(FR.mode==='walk'&&FR.next==='kursi')))return false;return true}
function pbTick(dt){PB.u=cl(PB.u+(PB.want?dt:-dt)/550,0,1)}
function withCtx(c,fn){const o=g;g=c;try{fn()}finally{g=o}}
function petDrop(){const p=S.pet;p.sc=SCA();PB.want=0;PB.u=0;const c=[[-70,14],[70,14],[0,40],[-40,-20],[50,-25]],q=c.find(a=>okC(ch.x+a[0],ch.y+a[1]))||c[0];p.x=ch.x+q[0];p.y=ch.y+q[1]}
function petArea(){const p=S.pet;if(p&&p.a&&p.mode==='follow'){petDrop();PWN.m='';if(BR.st==='free'){BR.al=120;BR.lt=0}}}
function petBuy(k){const q=PETS[k],p=S.pet;if(p.own[k])return;if((S.coin||0)<q.p)return toast('Koin kurang 🪙 Butuh '+q.p.toLocaleString('id-ID'));S.coin-=q.p;p.own[k]=1;p.a=k;p.mode='follow';petDrop();save();coinUp();toast(q.n+' kini menemanimu!');shop()}
function petUse(k){const p=S.pet;if(!p.own[k])return;p.a=k;p.mode='follow';petDrop();save();toast(PETS[k].n+' ikut denganmu');$('shp')?shop():petPanel()}
function petMode(m){const p=S.pet;if(!p.a)return;p.mode=m;if(m==='stay'){if(S.scene!=='dalam'||p.sc!=='dalam'){p.sc='dalam';if(S.scene!=='dalam'){p.x=p.a==='bird'?PHOME[0]:RUG[0];p.y=p.a==='bird'?PHOME[1]:RUG[1]}}p.sit=0;toast(PETS[p.a].n+(p.a==='bird'?' pulang ke rumah dan tidur di kursi goyang':' pulang ke rumah dan tidur di karpet'))}else{PB.want=0;if(p.sc!==SCA())petDrop();p.sit=0;toast(PETS[p.a].n+' ikut lagi')}save()}
function petPanel(){const p=S.pet,ks=Object.keys(PETS).filter(k=>p.own[k]);
 P(`<div class=hd><b>🐾 Pet</b></div><div class=bd>`+(ks.length?ks.map(k=>`<button class="song ${p.a===k?'hot':''}" onclick="petUse('${k}')">${pxSvg(PETS[k].ic).replace('<svg','<svg style="width:28px;height:24px;vertical-align:middle"')} ${PETS[k].n}${p.a===k?' · aktif':''}</button>`).join('')+'</div>'+(p.a?`<div class=ft><div class=tabs style="margin:0"><button onclick="petMode('follow');petPanel()" class="${p.mode==='follow'?'hot':''}">Ikut</button><button onclick="petMode('stay');petPanel()" class="${p.mode==='stay'?'hot':''}">Diam di rumah</button></div></div>`:''):'<small>Belum punya pet. Beli di 🛒 Toko, tab Pet.</small></div>'));$('m').classList.add('wide')}
$('pt').onclick=petPanel;
$('pb').onclick=()=>{audio();const p=S.pet;if(p.a)petMode(p.mode==='follow'?'stay':'follow')};
function updPet(dt){const p=S.pet;if(!p||!p.a)return;p.mv=0;
 if(p.mode==='follow'){
  if(p.sc!==S.scene){petDrop();return}
  if(T.boat){p.x=ch.x-44;p.y=ch.y-8;p.sit=1;return}
  const dx=ch.x-p.x,dy=ch.y-p.y,d=Math.hypot(dx,dy);
  if(d>700){petDrop();return}
  if(d>110){const v=Math.min(d-100,dt*.33),mx=dx/d*v,my=dy/d*v,ox=p.x,oy=p.y;step(p,mx,my);p.mv=1;p.sit=0;p.fd=dx>=0?1:-1;if(Math.abs(p.x-ox)+Math.abs(p.y-oy)<.01){p.st=(p.st||0)+dt;if(p.st>900||d>300){petDrop();p.st=0}}else p.st=0}
  else p.sit=d<70&&!ch.walk?1:p.sit}
 else{
  if(p.sc!=='dalam'||S.scene!=='dalam')return;
  const dx=PHOME[0]-p.x,dy=PHOME[1]-p.y,d=Math.hypot(dx,dy);
  if(d>8){const v=Math.min(d,dt*.25);step(p,dx/d*v,dy/d*v);p.mv=1;p.sit=0;p.fd=dx>=0?1:-1}else p.sit=1}}
function drawPet(t){const p=S.pet;if(!p||!p.a||p.sc!==S.scene)return;const q=PETS[p.a],c=pxCan(q.ic),k=q.sc*(S.scene==='luar'?1:1.5),w=c.width*k,h=c.height*k;
 const bob=p.mv?Math.abs(Math.sin(t/90))*5:Math.sin(t/500)*1.2,sq=p.sit?.9:1,x=p.x,y=p.y;
 g.save();g.fillStyle='rgba(20,10,30,.28)';g.beginPath();g.ellipse(x,y,w*.34,h*.07,0,0,7);g.fill();
 g.imageSmoothingEnabled=false;g.translate(x,y-bob);g.scale((p.fd||1)>=0?1:-1,1);g.drawImage(c,-w/2,-h*sq,w,h*sq);g.restore();
 if(p.mode==='stay'&&p.sit&&S.scene==='dalam'){const z=(t/1400)%1;g.save();g.globalAlpha=1-z;g.fillStyle='#dfe6ff';g.strokeStyle='#3a2535';g.lineWidth=4;g.font='bold 22px sans-serif';g.textAlign='center';g.strokeText('Z',x+w*.3+z*14,y-h-z*30);g.fillText('Z',x+w*.3+z*14,y-h-z*30);g.restore()}}
setInterval(()=>{const p=S.pet,b=$('pb');if(!p||!p.a){b.style.display='none';return}b.style.display='block';const f=p.mode==='follow';setIc(b,f?'home':'paw',f?PETS[p.a].n+': suruh diam di rumah':PETS[p.a].n+': panggil ikut');b.className=f?'':'hot'},300);

/* ===== PROFIL ===== */
Object.assign(PXI,{"user":["....kkkk....","...kssssk...","..kssssssk..","..kskssksk..","..kssssssk..","...kssssk...","....kkkk....","..kkoooookk.","..koooooook.","..koooooook.","..kkkkkkkkkk"]});
$("pr").innerHTML='<span class="pi">'+pxSvg("user")+'</span>';
const NAME_MAX=14;
const cleanName=v=>String(v||'').replace(/[\u0000-\u001f<>&"'`]/g,'').replace(/\s+/g,' ').trim().slice(0,NAME_MAX);
function profPaint(){const c=$('pfc');if(!c)return;const k=$('pfk');if(k)k.textContent=SEASONS[fo()].n+' · '+((HATS.find(a=>a[0]===hatK())||['','—'])[1]);try{render(c.getContext('2d'),{expr:'senang',pose:'berdiri',season:fo(),hat:hatK(),hair:S.fash.h,hairStyle:S.fash.s,acc:S.fash.acc||'',g:GEN(),blink:false,gx:0,gy:0},0,false)}catch(e){}}
setInterval(profPaint,300);
function profile(msg){
 const fishN=Object.values(S.fish||{}).reduce((a,b)=>a+(+b||0),0),guestN=Object.keys(S.guests||{}).length,gcN=Object.keys((S.gc&&S.gc.own)||{}).length,petN=Object.keys((S.pet&&S.pet.own)||{}).length;
 const nm=(S.name||'Players').replace(/</g,'&lt;');
 const st=[['📅','Hari',S.day],['🪙','Koin',(S.coin||0).toLocaleString('id-ID')],['🐟','Ikan',fishN],['🦌','Tamu',guestN],['🎰','Gacha',gcN],['🐾','Pet',petN]].map(a=>`<div class=pst><span class=psi>${a[0]}</span><span class=psv>${a[2]}</span><span class=psl>${a[1]}</span></div>`).join('');
 const hatN=(HATS.find(a=>a[0]===hatK())||['','—'])[1];
 P(`<div class=pft>Profil</div><div class=pf><div class=pfl><canvas id=pfc width=40 height=42></canvas><small id=pfk>${SEASONS[fo()].n} · ${hatN}</small><button onclick="fash()">👕 Ganti baju</button></div><div class=pfr><div class=pfh>Nama</div><div class=pfn>${nm}</div><div class=pfh>Ubah nama</div><div class=rcr><input type=text id=pn maxlength=${NAME_MAX} dir=ltr autocomplete=off autocorrect=off autocapitalize=words spellcheck=false style="direction:ltr;unicode-bidi:isolate;text-align:left" placeholder="Players"><button onclick="saveName()">Simpan</button></div><small class=pfs>Maks ${NAME_MAX} huruf. Kosongkan lalu simpan untuk kembali ke "Players".</small><div class=rcm id=pnm>${msg||''}</div></div></div><div class=pfh style="margin-top:10px">Statistik</div><div class=psg>${st}</div>`);
 $('m').classList.add('full');profPaint();
 const i=$('pn');if(i){i.value=S.name||'';let pv=i.value,mv=0;i.onkeydown=e=>{e.stopPropagation();if(e.key==='Enter')saveName();if(/^(Arrow|Home|End)/.test(e.key))mv=1};i.onkeyup=e=>e.stopPropagation();i.addEventListener('pointerdown',()=>{mv=1});const fixEnd=()=>{const v=i.value;if(!mv&&pv&&v.length===pv.length+1&&v.slice(1)===pv){i.value=pv+v[0]}try{const n=i.value.length;if(!mv&&document.activeElement===i)i.setSelectionRange(n,n)}catch(e){}pv=i.value;mv=0};i.addEventListener('input',fixEnd);i.addEventListener('compositionend',fixEnd)}}
function saveName(){const i=$('pn'),v=cleanName(i?i.value:'');S.name=v;save();toast('Halo, '+(v||'Players')+'!');profile('✔ Nama disimpan')}
$('pr').onclick=()=>profile();

/* ===== PET: gerak sendiri saat pemain diam + animasi tidur ===== */
const PWN={fly:0,fh:0,ft:rn(4000,15000),x:-1,y:-1,idle:0,m:'',tx:0,ty:0,wait:0,left:0,st:0,n:0};
const PET_IDLE=5000;
function petWander(dt){const p=S.pet;
 if(PWN.m==='sleep'){PWN.left-=dt;p.sit=1;if(p.a!=='bird'){PB.want=0;p.slp=1;if(PWN.left<=0){PWN.m='wait';PWN.wait=1800;p.slp=0}return}p.slp=PB.u>.9?1:0;if(PWN.left<=0||!pbFree()){PWN.m='wait';PWN.wait=1800;p.slp=0;PB.want=0}return}
 if(PWN.m==='go'){const dx=PWN.tx-p.x,dy=PWN.ty-p.y,d=Math.hypot(dx,dy);
  if(d>10){const v=Math.min(d,dt*.11*(1+.9*PWN.fh)),ox=p.x,oy=p.y;step(p,dx/d*v,dy/d*v);p.mv=1;p.sit=0;p.fd=dx>=0?1:-1;if(Math.abs(p.x-ox)+Math.abs(p.y-oy)<.01){PWN.st+=dt;if(PWN.st>500){PWN.bd=0;PWN.m='wait';PWN.wait=800;PWN.st=0}}else PWN.st=0}
  else{if(PWN.bd&&(p.a!=='bird'||pbFree())){PWN.bd=0;PWN.m='sleep';PWN.left=rn(10000,18000);PB.want=p.a==='bird'?1:0;p.sit=1;return}PWN.bd=0;PWN.m='wait';PWN.wait=rn(2000,4500);p.sit=Math.random()<.6?1:0}return}
 PWN.wait-=dt;if(PWN.wait>0)return;
 if(PWN.n>=2&&Math.random()<.35){if(PWN.fh>.02){PWN.fly=0;PWN.ft=rn(6000,15000);PWN.wait=900;return}PWN.n=0;if(S.scene==='dalam'&&!S.bk&&(p.a!=='bird'||pbFree())){const T2=p.a==='bird'?PCH.ap:RUG;PWN.tx=T2[0];PWN.ty=T2[1];PWN.bd=1;PWN.m='go';p.sit=0;return}PWN.wait=rn(3000,6000);p.sit=1;return}
 let a=0,tx,ty;do{tx=ch.x+rn(-450,450);ty=ch.y+rn(-260,260);a++}while(a<12&&!okC(tx,ty));
 if(a>=12){PWN.wait=1500;return}PWN.tx=tx;PWN.ty=ty;PWN.m='go';PWN.n++;p.sit=0}
function updPet0(dt){const p=S.pet;if(!p||!p.a)return;p.mv=0;p.slp=0;
 if(p.mode==='follow'){
  if(PWN.m!=='sleep')PB.want=0;if(p.sc!==SCA()){petDrop();PWN.idle=0;PWN.m='';return}
  const moved=Math.hypot(ch.x-PWN.x,ch.y-PWN.y)>1.5||!!T.boat||!!T.jm;PWN.x=ch.x;PWN.y=ch.y;
  PWN.idle=moved?0:PWN.idle+dt;
  if(T.boat){p.x=ch.x-44;p.y=ch.y-8;p.sit=1;return}
  const dx=ch.x-p.x,dy=ch.y-p.y,d=Math.hypot(dx,dy);
  if(d>700){petDrop();return}
  if(PWN.idle>=PET_IDLE&&d<=650){if(!PWN.m){PWN.m='wait';PWN.wait=600;PWN.n=0}petWander(dt);return}
  if(PWN.m){PWN.m='';PWN.st=0}
  if(d>110){const v=Math.min(d-100,dt*.33),mx=dx/d*v,my=dy/d*v,ox=p.x,oy=p.y;step(p,mx,my);p.mv=1;p.sit=0;p.fd=dx>=0?1:-1;if(Math.abs(p.x-ox)+Math.abs(p.y-oy)<.01){p.st=(p.st||0)+dt;if(p.st>900||d>300){petDrop();p.st=0}}else p.st=0}
  else p.sit=d<70&&!ch.walk?1:p.sit}
 else{
  PWN.m='';PWN.idle=0;
  if(p.sc!=='dalam'||S.scene!=='dalam')return;
  const dx=PHOME[0]-p.x,dy=PHOME[1]-p.y,d=Math.hypot(dx,dy);
  if(p.a!=='bird'){PB.want=0;const rx=RUG[0]-p.x,ry=RUG[1]-p.y,rd=Math.hypot(rx,ry);if(rd>8){const v=Math.min(rd,dt*.25),ox=p.x,oy=p.y;step(p,rx/rd*v,ry/rd*v);p.mv=1;p.sit=0;p.slp=0;p.fd=rx>=0?1:-1;if(Math.abs(p.x-ox)+Math.abs(p.y-oy)<.01){p.st=(p.st||0)+dt;if(p.st>700){p.x=RUG[0];p.y=RUG[1];p.st=0}}else p.st=0}else{p.sit=1;p.slp=1}return}
  const fr=pbFree();if(PB.want&&!fr)PB.want=0;
   if(PB.want){p.sit=1;p.slp=PB.u>.9?1:0;return}
   if(fr){const ax=PCH.ap[0]-p.x,ay=PCH.ap[1]-p.y,ad=Math.hypot(ax,ay);if(ad>8){const v=Math.min(ad,dt*.25);step(p,ax/ad*v,ay/ad*v);p.mv=1;p.sit=0;p.fd=ax>=0?1:-1}else{PB.want=1;p.sit=1}return}
   if(d>8){const v=Math.min(d,dt*.25);step(p,dx/d*v,dy/d*v);p.mv=1;p.sit=0;p.fd=dx>=0?1:-1}else{p.sit=1}}}
/* urutan tumpuk: pass 0 = di belakang karakter, pass 1 = di depan (naga terbang selalu di depan) */
function drawPet(t,pass){const p=S.pet;if(!p||!p.a||p.sc!==SCA())return;if(p.a==='bird'){const f=BR.st!=='free'||BR.al>6||p.y>=ch.y-2;if(((pass|0)===1)!==f)return;drawBird(t);return}const fly=PWN&&PWN.fh>.03,behind=!fly&&p.y<ch.y-2;if(((pass|0)===0)!==behind)return;drawPet0(t)}
function updPet(dt){const p=S.pet;if(!p||!p.a)return;
 pbTick(dt);if(p.a!=='bird'&&BR.st!=='free')BR.st='free';if(p.a==='bird'){updBird(dt);return}
 if(p.a==='dragon'&&p.mode==='follow'&&!T.boat&&PWN.m!=='sleep'){PWN.ft-=dt;if(PWN.ft<=0){PWN.fly=PWN.fly?0:1;PWN.ft=(PWN.fly?rn(20000,60000):rn(6000,22000))*(.6+Math.random()*.9)}}else{PWN.fly=0;if(PWN.m==='sleep')PWN.ft=rn(6000,15000)}
 const tg=PWN.fly?1:0;PWN.fh+=Math.sign(tg-PWN.fh)*Math.min(Math.abs(tg-PWN.fh),dt*.002);
 updPet0(dt);if(PWN.fh>.03){PB.want=0;p.sit=0;p.slp=0;if(PWN.m==='sleep'){PWN.m='wait';PWN.wait=500}}}
function dragWing(t,k,fd,far){const ph=Math.sin(t/(PWN.fh>.5?85:140)+(far?.6:0)),f=.78+.55*ph,rx=7.5+(far?2.2:0),ry=5,L=far?9:11,
  ox=a=>a*k,oy=a=>a*k;
 const pts=[[rx,ry],[rx-L*.5*Math.cos(f),ry-L*Math.sin(f)],[rx-L*1.0*Math.cos(f*.8)-1,ry-L*Math.sin(f)*.45],[rx-L*.85,ry+1.5*Math.sin(f)+1.5]];
 g.beginPath();pts.forEach((q,i)=>{const X=-0+q[0]*k,Y=q[1]*k;i?g.lineTo(X,Y):g.moveTo(X,Y)});g.closePath();
 g.fillStyle=far?'#6a4fb0':'#8f6bd0';g.fill();g.lineWidth=Math.max(2,k*.55);g.lineJoin='round';g.strokeStyle='#3a2535';g.stroke();
 g.beginPath();g.moveTo(pts[0][0]*k,pts[0][1]*k);g.lineTo(pts[2][0]*k,pts[2][1]*k);g.strokeStyle='#c9b3f0';g.lineWidth=Math.max(1,k*.3);g.stroke()}
/* pet ikut musim: sprite diberi warna tipis per musim (waktu & cuaca ikut dari light()) */
/* kaki sprite: deteksi baris kaki di bawah sprite, lalu angkat bergantian saat berjalan */
const LGI=new WeakMap();
function legInfo(c){let v=LGI.get(c);if(v!==undefined)return v;v=null;
 try{const w=c.width,h=c.height,d=c.getContext('2d').getImageData(0,0,w,h).data,occ=(x,y)=>d[(y*w+x)*4+3]>40,
  runsAt=y=>{const r=[];let a=-1;for(let x=0;x<=w;x++){const o=x<w&&occ(x,y);if(o&&a<0)a=x;if(!o&&a>=0){r.push([a,x-1]);a=-1}}return r};
  let bot=h-1;while(bot>0&&!runsAt(bot).length)bot--;const nb=runsAt(bot).length;
  if(nb>=2){let top=bot;while(top>0&&runsAt(top-1).length===nb&&bot-top<4)top--;
   if(bot-top>=1){const cols=new Array(w).fill(0);for(let y=top;y<=bot;y++)for(let x=0;x<w;x++)if(occ(x,y))cols[x]=1;
    const rs=[];let a=-1;for(let x=0;x<=w;x++){const o=x<w&&cols[x];if(o&&a<0)a=x;if(!o&&a>=0){rs.push([a,x-1]);a=-1}}
    if(rs.length>=2)v={top,bot,rs}}}}catch(e){}
 LGI.set(c,v);return v}
function legDraw(x,c,dx,dy,dw,dh,t,sp){const L=legInfo(c);
 if(!L){x.drawImage(c,dx,dy,dw,dh);return}
 const sx=dw/c.width,sy=dh/c.height,n=L.rs.length,gp=i=>n===4?(i===0||i===3?0:1):i%2;
 x.drawImage(c,0,0,c.width,L.top,dx,dy,dw,L.top*sy);
 L.rs.forEach((r,i)=>{const ph=Math.sin(t/(sp||95)+gp(i)*Math.PI),up=ph>.25?1:0,fw=ph>.25?1:0,sw=r[1]-r[0]+1;
  x.drawImage(c,r[0],L.top,sw,L.bot-L.top+1,dx+(r[0]+fw)*sx,dy+(L.top-up)*sy,sw*sx,(L.bot-L.top+1)*sy)})}
const PSC={},PSE=['rgba(150,230,140,.08)','rgba(255,196,90,.13)','rgba(255,130,50,.17)','rgba(150,190,255,.2)'];
function petSeason(ic,v){v=v<0?-1:1;const se=(S.se|0)%4,k=ic+se+'|'+v;if(PSC[k])return PSC[k];const c=pxCan(ic),o=document.createElement('canvas');o.width=c.width;o.height=c.height;const x=o.getContext('2d');x.drawImage(c,0,0);x.globalCompositeOperation='source-atop';x.fillStyle=PSE[se];x.fillRect(0,0,o.width,o.height);return PSC[k]=shadeCan(o,v)}
/* kaki kelinci: sprite hanya punya 1 baris kaki, jadi dipisah (badan baris 0-16, kaki baris 17-18) lalu diayun per fase lompatan.
   fase 0/1 = mendarat (kaki menapak), 0.5 = puncak (kaki belakang menjulur ke belakang, kaki depan terlipat ke depan) */
function bunnyHop(x,c,W,H,oy,t){
 const X=W/c.width,Y=H/c.height,ph=((t/135)%Math.PI)/Math.PI,a=Math.sin(ph*Math.PI),
  hA=.95*Math.pow(a,.8),fA=-.7*Math.pow(Math.sin(Math.min(1,ph*1.15)*Math.PI),.9),
  hS=1+.55*a,fS=1-.25*a;
 x.drawImage(c,0,0,c.width,17,0,oy,W,17*Y);
 x.drawImage(c,8,17,4,1,8*X,oy+17*Y,4*X,Y);
 const leg=(sx0,sw,px,ang,st)=>{x.save();x.translate(px*X,oy+17*Y);x.rotate(ang);x.scale(1,st);
  x.drawImage(c,sx0,17,sw,2,(sx0-px)*X,0,sw*X,2*Y);x.restore()};
 leg(3,6,6,hA,hS);
 leg(11,5,13,fA,fS)}
