function spMake(a,uri,res){const g=++SP.gen;try{SP.ctl&&SP.ctl.destroy&&SP.ctl.destroy()}catch(e){}SP.ctl=null;SP.ready=0;SP.started=0;SP.lp=-1;SP.lpT=Date.now();SP.rt0=Date.now();
 const h=spHost();h.innerHTML='<div id=spe></div>';
 a.createController($('spe'),{uri,width:'100%',height:SPH},c=>{if(g!==SP.gen){try{c.destroy()}catch(e){}return}SP.ctl=c;
  c.addListener('ready',()=>{if(g!==SP.gen)return;SP.ready=1;SP.rt0=Date.now();try{c.play()}catch(e){}if(res>2000)setTimeout(()=>{if(g===SP.gen)try{c.seek(res/1000)}catch(e){}},1500)});
  c.addListener('playback_started',e=>{if(g!==SP.gen)return;const d=e.data;SP.dbg='S:'+JSON.stringify(d).slice(0,160);if(d)spTu(d.playingURI||d.uri)});
  c.addListener('playback_update',e=>{if(g!==SP.gen)return;const d=e.data;if(!d)return;SP.dbg2='U:'+Object.keys(d).join(',')+' '+(d.playingURI||'');SP.pos=d.position||0;SP.dur=d.duration||0;SP.pa=!!d.isPaused;SP.ld=!!d.isBuffering;SP.t0=Date.now();
   if(d.position!==SP.lp){SP.lp=d.position;SP.lpT=Date.now()}
   if(!d.isPaused&&!d.isBuffering)SP.started=1;
   SP.prev=SP.dur>0&&SP.dur<=31000?1:0;
   spTu(d.playingURI||d.uri);
   if(!(d.playingURI||d.uri)&&SP.tl&&SP.dur>31000){const f=Object.keys(SP.tl).filter(u=>Math.abs(SP.tl[u].d-SP.dur)<1500);if(f.length===1)spTu(f[0])}
   const on=d.isPaused?0:1;if(on&&mix.on)mix.on=false;if(on!==SPP){SPP=on;gramoRefresh()}})})}
function spPlay(uri,name){SPP=0;SP.tt='';SP.tu='';SP.ta='';SP.tl=null;SP.uri=uri;SP.name=name||'';SP.pos=0;SP.dur=0;SP.pa=1;SP.ld=0;SP.want=1;SP.rt=0;SP.rc=0;SP.prev=0;mix.on=false;mix.am=false;mix.sh=false;const o=spLd();o.last={u:uri,n:name||''};spSv(o);spHost();
 if(/^spotify:(track|episode):/.test(uri))spTu(uri);else spList(uri);
 spLoad(a=>spMake(a,uri,0))}
function spRecover(){if(!SP.uri)return;const p=SP.prev?0:spCur(),u=SP.tu&&p>2000?SP.tu:SP.uri;SP.pa=1;SP.ld=1;spLoad(a=>spMake(a,u,p))}
function spReload(){if(!SP.uri)return;SP.rc=0;SP.rt=0;SP.want=1;toast('Memuat ulang pemutar…');spRecover()}
