function setIc(el,n,l){if(el.dataset.i!==n){el.dataset.i=n;el.innerHTML='<span class="pi">'+pxSvg(n)+'</span>'}if(el.getAttribute('aria-label')!==l){el.setAttribute('aria-label',l);el.title=l}}
