function joyMove(dt){let jx=J.x+((KEY.d||KEY.arrowright)?1:0)-((KEY.a||KEY.arrowleft)?1:0),jy=J.y+((KEY.s||KEY.arrowdown)?1:0)-((KEY.w||KEY.arrowup)?1:0);const m=Math.hypot(jx,jy);T.jm=m>.15&&T.sl<=0;
 if(T.jm){if(m>1){jx/=m;jy/=m}ch.act=null;X();if(T.fl){T.fl=null;if(!T.boat)$('fb').style.display='none';else ch.pose='berdiri'}
  if(T.boat&&S.scene==='luar'){const b=T.boat;if(Math.abs(jx)>.2)b.dir=jx>0?1:-1;stepB(b,jx*dt*.2,jy*dt*.2);b.tx=b.x;b.ty=b.y}else{if(ch.sit){const o=SEAT[ch.sit].out;ch.sit=0;ch.x=o[0];ch.y=o[1]}if(ch.pose!=='berdiri'&&T.cook<=0)ch.pose='berdiri';if(!okC(ch.x,ch.y)){const d=S.scene==='luar'?[632,505]:[700,770];ch.x=d[0];ch.y=d[1]}step(ch,jx*dt*.35,jy*dt*.35);ch.tx=ch.x;ch.ty=ch.y}}
 T.near=null;if(!T.boat){let bd=110;(S.kd?KDS:S.bk?BKS:S.scene==='luar'?OUTS:INS).forEach(s=>{const d=Math.hypot(s[5]-ch.x,s[6]-ch.y);if(d<bd){bd=d;T.near=s[0]}})}
 const a=$('ab'),l=T.near?NM[T.near]:'Tidak ada aksi';setIc(a,T.near?(ABI[T.near]||'dots'):'dots',l);a.classList.toggle('on',!!T.near)}
