const jyE=$('joy'),kn=$('knob');let jid=null;
function jset(e){const r=jyE.getBoundingClientRect(),R=r.width/2;let dx=(e.clientX-r.left-R)/R,dy=(e.clientY-r.top-R)/R;const m=Math.hypot(dx,dy);if(m>1){dx/=m;dy/=m}J.x=dx;J.y=dy;kn.style.transform=`translate(${dx*R*.55}px,${dy*R*.55}px)`}
jyE.onpointerdown=e=>{e.preventDefault();audio();try{screen.orientation.lock('landscape').catch(()=>{})}catch(x){}jid=e.pointerId;jset(e)};
addEventListener('pointermove',e=>{if(e.pointerId===jid)jset(e)});
const jend=e=>{if(e.pointerId===jid||e.type==='blur'){jid=null;J.x=J.y=0;kn.style.transform=''}};addEventListener('pointerup',jend);addEventListener('pointercancel',jend);addEventListener('blur',jend);addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('visibilitychange',()=>jend({type:'blur'}));
addEventListener('keydown',e=>{if(e.target.tagName==='TEXTAREA')return;KEY[e.key.length>1?e.key.toLowerCase():e.key.toLowerCase()]=1;if(e.key==='e'||e.key==='Enter')$('ab').click()});
addEventListener('keyup',e=>{KEY[e.key.toLowerCase()]=0});

/* batas peta */
function pip(px,py,poly){let c=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>py)!=(b[1]>py)&&px<(b[0]-a[0])*(py-a[1])/(b[1]-a[1])+a[0])c=!c}return c}
const DK=1.148,sp2=a=>a.map(p=>[p[0]*DK,p[1]*DK]);
const WALK=sp2([[190,410],[370,405],[480,440],[520,420],[580,420],[600,440],[700,432],[790,445],[860,470],[880,530],[840,560],[1150,560],[1150,596],[838,596],[830,640],[760,660],[745,720],[730,800],[620,800],[640,730],[590,650],[540,560],[500,520],[400,495],[300,475],[220,440]]);
const WATER=sp2([[1010,425],[1110,365],[1300,325],[1456,325],[1456,819],[800,819],[775,720],[830,650],[1200,650],[1200,548],[1000,548],[1010,470]]);
const BLK=[[1160,650,500,250],[1030,740,175,130]];
/* rute jalan: lewat sekeliling furnitur besar (kasur, peti), bukan menembusnya */
function segHitR(x0,y0,x1,y1,r){let t0=0,t1=1;const dx=x1-x0,dy=y1-y0,P=[-dx,dx,-dy,dy],Q=[x0-r[0],r[0]+r[2]-x0,y0-r[1],r[1]+r[3]-y0];
 for(let i=0;i<4;i++){if(P[i]===0){if(Q[i]<0)return false}else{const u=Q[i]/P[i];if(P[i]<0){if(u>t1)return false;if(u>t0)t0=u}else{if(u<t0)return false;if(u<t1)t1=u}}}return t0<=t1}
function routePts(ax,ay,bx,by,dep){if(dep>3||S.scene!=='dalam')return[];
 for(const b of BLK){const r=[b[0]-10,b[1]-8,b[2]+20,b[3]+16];if(!segHitR(ax,ay,bx,by,r))continue;
  const cs=[[r[0],r[1]],[r[0]+r[2],r[1]],[r[0],r[1]+r[3]],[r[0]+r[2],r[1]+r[3]]].filter(c=>c[0]>=70&&c[0]<=1610&&c[1]>=612&&c[1]<=890&&!BLK.some(q=>q!==b&&c[0]>q[0]-10&&c[0]<q[0]+q[2]+10&&c[1]>q[1]-8&&c[1]<q[1]+q[3]+8));
  let best=null,bd=1e9;cs.forEach(c=>{const d=Math.hypot(c[0]-ax,c[1]-ay)+Math.hypot(bx-c[0],by-c[1]);if(d<bd){bd=d;best=c}});
  if(!best)return[];return[...routePts(ax,ay,best[0],best[1],dep+1),best,...routePts(best[0],best[1],bx,by,dep+1)]}
 return[]}
function nextT(o,x,y,tx,ty){const k=tx+','+ty+','+S.scene;if(o._k!==k){o._k=k;o._w=routePts(x,y,tx,ty,0)}
 while(o._w.length&&Math.hypot(o._w[0][0]-x,o._w[0][1]-y)<8)o._w.shift();return o._w.length?o._w[0]:[tx,ty]}
function okC(x,y){if(S.kd)return pip(x,y,window.KWALK);if(S.bk)return pip(x,y,BWALK);if(S.scene==='luar')return pip(x,y,WALK);if(x<70||x>1610||y<(x>1090&&x<1400?612:650)||y>890)return false;return !BLK.some(r=>x>r[0]&&x<r[0]+r[2]&&y>r[1]&&y<r[1]+r[3])}
function step(o,dx,dy){if(okC(o.x+dx,o.y))o.x+=dx;if(okC(o.x,o.y+dy))o.y+=dy}
function stepB(b,dx,dy){let m=0;if(pip(b.x+dx,b.y,WATER)){b.x+=dx;m=1}if(pip(b.x,b.y+dy,WATER)){b.y+=dy;m=1}return m}

/* pancing & tidur */
function drawFish(t,cx,cy,sc){const f=T.fl;if(!f)return;const d=T.boat&&T.boat.dir<0?-1:1,rx=cx+d*(FSW+18.5*sc),ry=cy+FSY-22*sc,tx=rx+d*26,ty=ry-30;
 g.strokeStyle='#7a4a2a';g.lineWidth=4;g.beginPath();g.moveTo(rx,ry);g.lineTo(tx,ty);g.stroke();
 if(f.s==='idle'||f.s==='charge'){if(f.s==='charge'){const bx=cx-60,by=cy-37*sc-30;g.fillStyle='rgba(58,37,53,.85)';g.fillRect(bx-4,by-4,128,20);g.fillStyle=f.pw>.85?'#ff6a4a':'#ffd27a';g.fillRect(bx,by,120*f.pw,12)}return}
 const u=f.s==='fly'?f.u:1,px=tx+(f.bx-tx)*u,py=ty+(f.by-ty)*u-(f.s==='fly'?140*Math.sin(Math.PI*u):0)+(f.s==='b'?6+Math.sin(t/50)*3:0);
 g.strokeStyle='rgba(235,240,250,.9)';g.lineWidth=2;g.beginPath();g.moveTo(tx,ty);g.quadraticCurveTo((tx+px)/2,(ty+py)/2+(f.s==='fly'?-60:28),px,py);g.stroke();
 if(u>=1){const k=(t/700)%1;g.strokeStyle=`rgba(255,255,255,${(1-k)*.6})`;g.lineWidth=2;g.beginPath();g.ellipse(px,py+4,12+k*(f.s==='b'?30:16),4+k*(f.s==='b'?10:5),0,0,7);g.stroke()}
 g.fillStyle='#e84a4a';g.beginPath();g.arc(px,py,8,Math.PI,0);g.fill();g.fillStyle='#fff';g.beginPath();g.arc(px,py,8,0,Math.PI);g.fill();
 if(f.s==='b'){g.fillStyle='#fff';g.strokeStyle='#3a2535';g.lineWidth=5;g.font='bold 48px sans-serif';g.textAlign='center';g.strokeText('!',px,py-34);g.fillText('!',px,py-34)}}
function zzz(t){g.textAlign='center';for(let i=0;i<3;i++){const p=(t/1400+i/3)%1;g.globalAlpha=1-p;g.fillStyle='#dfe6ff';g.strokeStyle='#3a2535';g.lineWidth=4;g.font=`bold ${22+p*26+i*4}px sans-serif`;const x=1500+p*50+i*8,y=612-p*100;g.strokeText('Z',x,y);g.fillText('Z',x,y)}g.globalAlpha=1}

