const fo=()=>SEASONS[S.fash.o]?S.fash.o:SK[S.se];
function fash(){const F=S.fash,bt=(c,a,f)=>`<button class="${c?'hot':''}" onclick="${f}">${a}</button>`;
 P(`<b>Lemari baju</b><canvas id=fp width=40 height=42 style="width:160px;height:168px;image-rendering:pixelated;display:block;margin:4px auto;background:#e8dcc0;border:3px solid #3a2535;border-radius:8px"></canvas>Baju:<br>${bt(F.o==='auto','Otomatis (musim)',"fset('o','auto')")}${Object.keys(SEASONS).map(k=>bt(F.o===k,SEASONS[k].n,`fset('o','${k}')`)).join('')}<br>Warna rambut:<br>${HAIRS.map((h,i)=>bt(F.h===i,h.n,`fset('h',${i})`)).join('')}<br>Gaya rambut:<br>${Object.keys(HAIR_STYLES).map(k=>bt(F.s===k,HAIR_STYLES[k].n,`fset('s','${k}')`)).join('')}`);
 render($('fp').getContext('2d'),{expr:'senang',pose:'berdiri',season:fo(),hair:F.h,hairStyle:F.s,blink:false,gx:0,gy:0},0,false)}
