const GEN=()=>S.fash.g||'m',own=id=>!!S.gc.own[id],okG=it=>!it||it.g==='u'||it.g===GEN();
const ACCS=['kacamata','jepit','bunga','syal','headphone','rubah','penyihir','halo','tanduk','sayap','rusa','mahkotabunga','kelinci','kupu','tandukiblis','sayaphitam','pitarambut','baretkrem','tas'];
const pvc=(o,hat,hr,hs,acc,g)=>`<canvas class=pv width=40 height=42 data-o="${o}" data-hat="${hat}" data-hr="${hr}" data-s="${hs}" data-acc="${acc||''}" data-g="${g||GEN()}"></canvas>`;
function paintPV(){document.querySelectorAll('#m canvas.pv').forEach(c=>{const d=c.dataset;render(c.getContext('2d'),{expr:'biasa',pose:'berdiri',season:d.o,hat:d.hat,hair:+d.hr,hairStyle:d.s,acc:d.acc,g:d.g,blink:false,gx:0,gy:0},0,false)});
 const fp=$('fp');if(fp)render(fp.getContext('2d'),{expr:'senang',pose:'berdiri',season:fo(),hat:hatK(),hair:S.fash.h,hairStyle:S.fash.s,acc:S.fash.acc||'',g:GEN(),blink:false,gx:0,gy:0},0,false)}
function fash(){
 const F=S.fash,cur=hatK(),g=GEN(),acc=F.acc||'';
 const tab=(k,l)=>`<button class="${FT===k?'hot':''}" onclick="FT='${k}';fash()">${l}</button>`;
 const gb=(k,l)=>`<button class="${g===k?'hot':''}" onclick="fset('g','${k}')">${l}</button>`;
 let body='';
 if(FT==='baju'){
  const ks=['auto',...Object.keys(SEASONS).filter(k=>!SEASONS[k].x&&(!SEASONS[k].g||SEASONS[k].g===g)),...Object.keys(SEASONS).filter(k=>SEASONS[k].x&&own('o:'+k)&&okG(GIM['o:'+k]))];
  body=ks.map(k=>{const real=k==='auto'?SK[S.se]:k,on=F.o===k||(!SEASONS[F.o]&&k==='auto');return slot(k==='auto'?1:(RAR[k]||(GIM['o:'+k]||{}).r||1),pvc(real,cur,F.h,F.s,acc),on,`fset('o','${k}')`,null,k==='auto'?'Otomatis':SEASONS[k].n,on)}).join('');
 }else if(FT==='topi'){
  body=HATS.map(([k,n,r])=>{const on=(F.hat||'auto')===k;return slot(r,pvc(fo(),k==='auto'?fo():k,F.h,F.s,acc),on,`fset('hat','${k}')`,null,n,on)}).join('');
 }else if(FT==='rambut'){
  body=HAIRS.map((h,i)=>({h,i})).filter(o=>!o.h.x||own('c:'+o.i)).map(({h,i})=>slot((GIM['c:'+i]||{}).r||2,`<div class=sw style="background:${h.c}"></div>`,F.h===i,`fset('h',${i})`,null,h.n,F.h===i)).join('')+
   Object.keys(HAIR_STYLES).filter(k=>HAIR_STYLES[k].x?(own('s:'+k)&&okG(GIM['s:'+k])):(!HAIR_STYLES[k].g||HAIR_STYLES[k].g===g)).map(k=>{const on=F.s===k;return slot((GIM['s:'+k]||{}).r||3,pvc(fo(),cur,F.h,k,acc),on,`fset('s','${k}')`,null,HAIR_STYLES[k].n,on)}).join('');
 }else{
  body=['none',...ACCS.filter(k=>own('a:'+k)&&okG(GIM['a:'+k]))].map(k=>{const on=acc===k||(k==='none'&&!acc);return slot(k==='none'?1:GIM['a:'+k].r,pvc(fo(),'none',F.h,F.s,k==='none'?'':k),on,`fset('acc','${k==='none'?'':k}')`,null,k==='none'?'Tanpa':GIM['a:'+k].n,on)}).join('');
  if(ACCS.every(k=>!own('a:'+k)))body+='<div style="grid-column:1/-1"><small>Belum punya aksesori. Coba Gacha.</small></div>';
 }
 P(`<div class=hd><b>Lemari baju</b><div class=tabs>${gb('m','Cowok')}${gb('f','Cewek')}<button onclick="gacha()">🎰 Gacha</button></div></div>
 <div class=fx><div class=pvw><div class=dt style="min-height:0"><canvas id=fp width=40 height=42 style="width:100%;image-rendering:pixelated;display:block;background:#e8dcc0;border:3px solid #3a2535;border-radius:8px"></canvas><small>${SEASONS[fo()].n} · ${(HATS.find(a=>a[0]===cur)||['','—'])[1]}</small></div></div><div class="tabs vt">${tab('baju','👕 Baju')}${tab('topi','🎩 Topi')}${tab('rambut','💇 Rambut')}${tab('acc','✨ Aksesori')}</div><div class=gd><div class=gi>${body}</div></div></div>`);
 $('m').classList.add('wide');paintPV()}
