/* ===== Gacha kapsul ===== */
const GC1=250,GC10=2250,GW=[[2,45],[3,30],[4,18],[5,7]],GDUP={2:5,3:10,4:25,5:60};
let GR=null,GBUSY=0;
function gRoll(force){let x=Math.random()*100,rar=5;for(const [q,w] of GW){if(x<w){rar=q;break}x-=w}if(force&&rar<4)rar=4;const pool=GI.filter(a=>a[3]===rar);return pool[Math.random()*pool.length|0][0]}
function itemPV(id){const [t,k]=id.split(':'),it=GIM[id],F=S.fash;let o='semi',hr=F.h,hs=F.s,acc='';const g=it.g==='u'?GEN():it.g;if(t==='o')o=k;else if(t==='c')hr=+k;else if(t==='s')hs=k;else acc=k;return pvc(o,'none',hr,hs,acc,g)}
function gPull(n){
 if(GBUSY)return;const cost=n===10?GC10:GC1;
 if((S.coin||0)<cost){toast('Koin kurang. Jual ikan dulu di toko');return}
 S.coin-=cost;const out=[];
 for(let i=0;i<n;i++){const force=S.gc.pity>=9,id=gRoll(force),it=GIM[id];S.gc.pity=it.r>=4?0:S.gc.pity+1;let dup=0;if(own(id)){dup=GDUP[it.r];S.coin+=dup}else S.gc.own[id]=1;out.push({id,dup})}
 GBUSY=1;GR=null;save();coinUp();gacha();
 setTimeout(()=>{GBUSY=0;GR=out;save();if($('m').querySelector('.gm'))gacha()},1100)}
function gEquip(id){const [t,k]=id.split(':'),it=GIM[id],F=S.fash;if(it.g!=='u')F.g=it.g;if(t==='o')F.o=k;else if(t==='s')F.s=k;else if(t==='c')F.h=+k;else F.acc=k;save();toast('Dipakai: '+it.n)}
function gShow(){
 if(GBUSY)return '<div class="gsh gbz"><div class=gbt>Kapsul berputar…</div></div>';
 const c=S.gc,tot=GI.length,got=GI.filter(a=>own(a[0])).length,left=Math.max(1,10-c.pity),
  gt=g=>g==='m'?'♂':g==='f'?'♀':null,
  chips=GW.map(([q,w])=>`<span style="background:linear-gradient(160deg,${RC[q][0]},${RC[q][1]})">★${q} ${w}%</span>`).join(''),
  seg=Array.from({length:10},(_,i)=>`<i class="${i<c.pity?'f':''}"></i>`).join(''),
  tops=GI.filter(a=>a[3]===5).map(([id,n,g,r])=>slot(r,itemPV(id),false,'GR=null;GLT=5;gList()',gt(g),n,own(id))).join('');
 return `<div class=gsh><div class=grt>${chips}</div><div class=gpt><span>★4 pasti ${left}×</span><div class=bar>${seg}</div><span>${got}/${tot}</span></div><div class=gnt>Hadiah utama ★5 · ketuk untuk lihat daftar</div><div class=gi>${tops}</div></div>`}
function gacha(){
 const c=S.gc,tot=GI.length,got=GI.filter(a=>own(a[0])).length,dis=GBUSY?' disabled':'';
 const res=GR?`<div class=gi>${GR.map(r=>{const it=GIM[r.id];return slot(it.r,itemPV(r.id),false,`gEquip('${r.id}')`,r.dup?'+🪙'+r.dup:null,it.n,false)}).join('')}</div><small>Ketuk hasil untuk langsung memakainya.${GR.some(r=>r.dup)?' Duplikat ditukar jadi koin.':''}</small>`:gShow();
 P(`<div class=hd><b>Gacha Kapsul</b><span class=cn>🪙 ${S.coin||0}</span></div><div class=gx><div class=gxl><div class="gm${GBUSY?' shake':''}"><div class=gmc>${pxSvg('capsule')}</div></div><button class=hot${dis} onclick="gPull(1)">Tarik 1× · 🪙${GC1}</button><button${dis} onclick="gPull(10)">Tarik 10× · 🪙${GC10}</button></div><div class=gxr><small>Tukar koin hasil mancing dengan baju, rambut, dan aksesori untuk cowok dan cewek.</small><small>Koleksi ${got}/${tot} · ★4 pasti dalam ${Math.max(1,10-c.pity)} tarikan<br>Peluang ★2 45% · ★3 30% · ★4 18% · ★5 7%</small><div class=gres>${res}</div><div class=tabs style="margin:0"><button onclick="GR=null;gList()">📖 Daftar hadiah ${got}/${tot}</button><button onclick="GR=null;fash()">Buka lemari</button></div></div></div>`);
 $('m').classList.add('wide');paintPV()}

/* ===== Daftar hadiah gacha: sudah / belum dapat ===== */
let GLT=0;
function gList(){
 const gt=g=>g==='m'?'♂':g==='f'?'♀':null;
 const tabs=[0,5,4,3,2].map(r=>{const a=GI.filter(x=>!r||x[3]===r);return `<button class="${GLT===r?'hot':''}" onclick="GLT=${r};gList()">${r?'★'+r:'Semua'} ${a.filter(x=>own(x[0])).length}/${a.length}</button>`}).join('');
 const list=GI.filter(x=>!GLT||x[3]===GLT).sort((x,y)=>y[3]-x[3]);
 const cells=list.map(([id,n,g,r])=>{const o=own(id);
  const inner=`<div style="display:flex;align-items:center;justify-content:center;width:100%;height:100%${o?'':';filter:grayscale(1) brightness(.45);opacity:.8'}">${itemPV(id)}</div>`;
  return slot(r,inner,false,o?`gEquip('${id}')`:'',gt(g),n,o)}).join('');
 P(`<div class=hd><b>Daftar Hadiah</b><small>${GI.filter(a=>own(a[0])).length}/${GI.length}</small><div class=tabs>${tabs}</div></div><div class=fx><div class=gd><div class=gi>${cells}</div></div></div><div class=ft><small>✅ sudah dapat (ketuk untuk pakai) · gelap = belum · ♂ cowok · ♀ cewek</small><button onclick="gacha()">Kembali</button></div>`);
 $('m').classList.add('wide');paintPV()}
