const ITM={kayu:['Kayu Bakar','🪵',1,'Bahan','Kayu kering untuk menyalakan perapian.'],umpan:['Umpan','🪱',1,'Bahan','Dipakai untuk memancing di dermaga atau perahu.'],benih:['Benih','🌱',1,'Bahan','Tanam di kebun dekat pondok.'],herb:['Daun Herbal','🌿',2,'Bahan','Dipetik dari kebun. Bisa diseduh jadi teh.'],teh:['Teh Herbal','🍵',3,'Makanan','Hangat dan menenangkan. Sudah pernah dinikmati sebanyak ini.'],sup:['Sup Ikan','🍲',3,'Makanan','Sup hangat dari hasil danau. Sudah pernah dinikmati sebanyak ini.']};
let BT='Semua',BS=null;
const fishR=w=>w>=40?1:w>=25?2:w>=14?3:w>=8?4:5;
function bagItems(){const L=[];for(const k in ITM)if(S.inv[k]>0)L.push({id:k,n:ITM[k][0],ic:`<span class=ic>${ITM[k][1]}</span>`,big:ITM[k][1],r:ITM[k][2],t:ITM[k][3],c:S.inv[k],d:ITM[k][4]});
 for(const k in S.fish)if(S.fish[k]>0){const f=FISH.find(a=>a[0]===k)||[k,20,'#999'];L.push({id:'f:'+k,n:k,ic:fsvg(f[2],f[1]<=8),big:fsvg(f[2],f[1]<=8),r:fishR(f[1]),t:'Ikan',c:S.fish[k],d:f[1]<=8?'Ikan langka dari danau yang jarang muncul.':'Hasil tangkapan dari danau di depan pondok.'})}
 return L}
function bag(){
 const all=bagItems(),tabs=['Semua','Bahan','Makanan','Ikan','Lainnya'];
 const shown=BT==='Semua'?all:all.filter(i=>i.t===BT);
 if(!shown.find(i=>i.id===BS))BS=shown[0]?shown[0].id:null;
 const it=shown.find(i=>i.id===BS);
 let grid='';
 if(BT==='Lainnya')grid='';
 else{const cells=shown.map(i=>slot(i.r,i.ic,i.id===BS,`BS='${i.id.replace(/'/g,"\\'")}';bag()`,i.c));const n=Math.max(12,cells.length);for(let i=cells.length;i<n;i++)cells.push('<div class="sl em"></div>');grid=cells.join('')}
 let det;
 if(BT==='Lainnya')det=`<div class=dt style="text-align:left"><b>Tamu hutan</b><br>${Object.keys(S.guests).join(', ')||'<small>belum ada</small>'}<hr><b>Dekorasi</b><br>${S.deco.join(', ')||'<small>belum ada</small>'}</div>`;
 else if(it)det=`<div class=dt><div class=big>${it.big}</div><b>${it.n}</b><span class=str>${stars(it.r)}</span><small>${it.t} · ×${it.c}</small><hr><small>${it.d}</small><div class=ba>${it.id.startsWith('f:')?`<button onclick="sellFish('${it.id.slice(2)}',1)">Jual 1 · 🪙${fprice(it.id.slice(2))}</button><button onclick="sellFish('${it.id.slice(2)}',${it.c})">Jual semua · 🪙${fprice(it.id.slice(2))*it.c}</button>`:''}${it.id==='herb'?'<button onclick="cook(\'teh\')">🍵 Seduh teh</button>':''}${it.id==='kayu'?'<button onclick="wood()">🔥 Tambah ke api</button>':''}</div></div>`;
 else det='<div class=dt><small>Tas masih kosong</small></div>';
 P(`<div class=hd><b>🎒 Tas</b> <small>${all.reduce((a,i)=>a+i.c,0)} barang</small><div class=tabs>${tabs.map(t=>`<button class="${BT===t?'hot':''}" onclick="BT='${t}';bag()">${t}</button>`).join('')}</div></div>
 <div class=fx><div class=gd>${BT==='Lainnya'?'':`<div class=gi style="--cols:4">${grid}</div>`}</div><div class=pvw${BT==='Lainnya'?' style="width:100%!important"':''}>${det}</div></div>`);
 $('m').classList.add('wide')}
$('bg').onclick=bag;

