const ms={step:0,next:0,p:-1,lt:0,st:0,dur:150000};
function nz(t,ft,fr,g,d){const c=A.c,s=c.createBufferSource();s.buffer=A.nb;const f=c.createBiquadFilter();f.type=ft;f.frequency.value=fr;const q=c.createGain();q.gain.setValueAtTime(g,t);q.gain.exponentialRampToValueAtTime(.001,t+d);s.connect(f);f.connect(q);q.connect(A.mu);s.start(t,Math.random()*1.5);s.stop(t+d+.05)}
function tn(t,fr,ty,g,at,d,dest){const c=A.c,o=c.createOscillator(),q=c.createGain();o.type=ty;o.frequency.value=fr;q.gain.setValueAtTime(0,t);q.gain.linearRampToValueAtTime(g,t+at);q.gain.exponentialRampToValueAtTime(.0008,t+d);o.connect(q);q.connect(dest||A.mu);o.start(t);o.stop(t+d+.05)}
function seqStep(sg,st,t,spb){
 const ch=sg.pr[Math.floor(st/16)%sg.pr.length],r=ch[0],iv=ch[1],s=st%16,bar=spb*16;
 if(sg.jz)return jazzStep(sg,st,t,spb,r,iv,s);
 if(sg.pad&&s===0)iv.forEach(i=>tn(t,mid(r+12+i),'sine',.045*sg.pad,.5,bar*1.05));
 if(sg.bass&&(s===0||s===8))tn(t,mid(r-12),'sine',.22,.02,spb*6);
 if(sg.walk&&s%4===0)tn(t,mid(r-12+[0,iv[1],iv[2],iv[1]][s/4|0]),'triangle',.18,.02,spb*3.5);
 if(sg.arp&&(sg.arp===2?s%2===0:(sg.arp===.5?s%4===2:s%2===0))){const n=iv[(st>>1)%iv.length]+(sg.arp===2&&((st>>1)%8>3)?12:0);tn(t,mid(r+24+n),'triangle',.09,.01,spb*3)}
 if(sg.bell&&(s===0||s===6||s===10)&&Math.random()<.7){const n=r+24+iv[Math.random()*iv.length|0];tn(t,mid(n),'sine',.07,.01,2.6);tn(t,mid(n)*2.76,'sine',.02,.01,1.2)}
 if(sg.mel&&s%2===0&&Math.random()<sg.mel*.5){const n=sg.sc[Math.random()*sg.sc.length|0];tn(t,mid(n),'triangle',.1,.02,spb*5)}
 if(sg.drum){const d=sg.drum;
  if(d===1||d===2){if(s===0||s===10)kick(t,.35);if(s===4||s===12)nz(t,'bandpass',1800,d===1?.13:.08,.12);if(s%2===0)nz(t,'highpass',7000,.04+Math.random()*.03,.05)}
  if(d===3){if(s%4===0)kick(t,.3);if(s===4||s===12)nz(t,'bandpass',2000,.1,.1);if(s%2===1)nz(t,'highpass',7500,.03,.04)}}
}
/* jazz: walking bass, piano komping, ride swing, improvisasi */
function jazzStep(sg,st,t,spb,r,iv,s){
 const J=sg.jz,nr=sg.pr[(Math.floor(st/16)+1)%sg.pr.length][0],sw=J===3?0:spb*.67,
  tt=(s%4===2)?t+sw:t,pick=()=>iv[Math.random()*iv.length|0];
 if(s===0&&!ms.ji)ms.ji=4;
 /* bass */
 if(J===1){if(s%4===0){const b=s/4,n=[r-12,r-12+iv[1],r-12+iv[2],nr-12+(nr>r?-1:1)][b];tn(t,mid(n),'triangle',.24,.015,spb*3.6)}}
 else if(J===4){if(s%4===0){const b=s/4,n=[r-12,r-12+iv[2],r-12+iv[1],nr-12+(nr>r?-1:1)][b];tn(t,mid(n),'triangle',.19,.02,spb*3.6)}}
 else if(J===2){if(s===0)tn(t,mid(r-12),'triangle',.22,.02,spb*7);if(s===8)tn(t,mid(r-12+iv[2]),'triangle',.18,.02,spb*6);if(s===14)tn(t,mid(nr-12+(nr>r?-1:1)),'triangle',.12,.02,spb*2)}
 else{if(s===0||s===8)tn(t,mid(r-12),'triangle',.24,.015,spb*5);if(s===6||s===14)tn(t,mid(r-12+iv[2]),'triangle',.2,.015,spb*4)}
 /* piano / rhodes */
 const stab=(k,g,d)=>{iv.forEach((i,x)=>{const n=r+12+i;tn(t+x*.012,mid(n),'sine',g,.01,d);tn(t+x*.012,mid(n)*2,'sine',g*.18,.01,d*.4)})};
 if(J===1){if(s===0&&Math.random()<.6)stab(0,.04,spb*6);if(s===6)stab(0,.045,spb*5);if(s===10&&Math.random()<.4)stab(0,.035,spb*4)}
 else if(J===4){if(s===0)stab(0,.035,spb*8);if(s===8&&Math.random()<.6)stab(0,.025,spb*6)}
 else if(J===2){if(s===0)stab(0,.035,spb*14);if(s===10&&Math.random()<.5)stab(0,.025,spb*5)}
 else{if(s===0||s===6||s===8||s===14){const g=s===0?.04:.03;stab(0,g,spb*3)}}
 /* drum */
 if(J===1){if(s===0||s===4||s===8||s===12)nz(tt,'highpass',8000,.05,.22);if(s===6||s===14)nz(tt,'highpass',8000,.035,.15);
  if(s===4||s===12)nz(t,'highpass',5500,.05,.05);if(s%4===0)kick(t,.07);if(s===10&&Math.random()<.35)nz(tt,'bandpass',1800,.05,.08)}
 else if(J===4){if(s%4===0)nz(t,'highpass',7500,.03,.4);if(s===6||s===14)nz(tt,'highpass',7500,.02,.2);if(s===4||s===12)nz(t,'highpass',5000,.03,.07);if(s===0||s===8)kick(t,.05)}
 else if(J===2){if(s%4===0)nz(t,'highpass',7500,.03,.5);if(s===4||s===12)nz(t,'highpass',5000,.03,.08);if(s===0)kick(t,.06)}
 else{if(s%2===0)nz(t,'highpass',7500,.03,.05);if([0,6,12].includes(s)||(Math.floor(st/16)%2&&s===4))nz(t,'bandpass',2600,.07,.04);if(s===0||s===8)kick(t,.1)}
 /* improvisasi: tangga nada + target nada akor di ketukan kuat */
 if(sg.imp&&s%2===0){
  if(s===0&&Math.random()<.8){const tgt=r+24+pick(),sc=sg.sc;let b=0;sc.forEach((n,i)=>{if(Math.abs(n-tgt)<Math.abs(sc[b]-tgt))b=i});ms.ji=b;tn(tt,mid(sc[b]),'triangle',.09,.03,spb*5)}
  else if(Math.random()<sg.imp*.6){const sc=sg.sc;ms.ji=cl(ms.ji+[-2,-1,-1,1,1,2][Math.random()*6|0],0,sc.length-1);const n=sc[ms.ji];tn(tt,mid(n),'triangle',.085,.025,spb*(J===2?6:J===4?4.5:3.2));if(J!==2&&Math.random()<.2)tn(tt+spb*1.5,mid(n+1),'triangle',.05,.02,spb*1.5)}
 }
}
function kick(t,g){const c=A.c,o=c.createOscillator(),q=c.createGain();o.frequency.setValueAtTime(130,t);o.frequency.exponentialRampToValueAtTime(42,t+.14);q.gain.setValueAtTime(g,t);q.gain.exponentialRampToValueAtTime(.001,t+.25);o.connect(q);q.connect(A.mu);o.start(t);o.stop(t+.3)}
