const udbDo=(mode,fn)=>new Promise(r=>{if(!udb)return r(null);try{const t=udb.transaction('f',mode),st=t.objectStore('f'),q=fn(st);t.oncomplete=()=>r(q&&q.result!==undefined?q.result:true);t.onerror=t.onabort=()=>r(null)}catch(e){r(null)}});
function userTrack(name,blob,id){const t={n:name,rec:1,u:1,id,src:URL.createObjectURL(blob)};MUS.push(t);return t}
async function addMusic(files){
 const ok=[...files].filter(f=>/^audio\//.test(f.type)||/\.(mp3|m4a|aac|ogg|oga|opus|wav|flac|weba|webm)$/i.test(f.name));
 if(!ok.length){toast('Pilih file musik (mp3, m4a, wav, ogg…)');return}
 if(!udb)await udbOpen();let n=0,saved=true;
 for(const f of ok){const id=await udbDo('readwrite',st=>st.add({name:f.name,blob:f}));if(id===null)saved=false;
  userTrack(f.name.replace(/\.[^.]+$/,''),f,id);n++}
 toast(n+' musik ditambahkan'+(saved?'':' (tidak tersimpan, penyimpanan penuh/ditolak)'));gramoRefresh();
 const i=document.getElementById('upl');if(i)i.value=''}
let delAsk=null,delTm=0;
function delClick(i){const t=MUS[i];if(!t||!t.u)return;
 if(delAsk===t){clearTimeout(delTm);delAsk=null;delMusic(i);return}
 delAsk=t;clearTimeout(delTm);delTm=setTimeout(()=>{delAsk=null;gramoRefresh()},4000);gramoRefresh()}
async function delMusic(i){
 const t=MUS[i];if(!t||!t.u)return;const cur=mix.p;
 if(cur===i){mix.on=false;REC.pause();REC._k=null}
 MUS.splice(i,1);if(cur>i)mix.p=cur-1;else if(cur===i)mix.p=0;
 try{URL.revokeObjectURL(t.src)}catch(e){}
 if(t.id!==null&&t.id!==undefined)await udbDo('readwrite',st=>st.delete(t.id));
 toast('Musik dihapus');gramoRefresh()}
udbOpen().then(async d=>{if(!d)return;await new Promise(r=>{try{const t=d.transaction('f','readonly'),c=t.objectStore('f').openCursor();
 c.onsuccess=()=>{const k=c.result;if(k){const v=k.value;if(v&&v.blob)userTrack(String(v.name).replace(/\.[^.]+$/,''),v.blob,k.key);k.continue()}};t.oncomplete=t.onerror=t.onabort=()=>r()}catch(e){r()}});gramoRefresh()});
setInterval(()=>{if(mix.sh&&mix.on&&MUS[mix.p]&&!MUS[mix.p].rec&&Date.now()-ms.st>ms.dur)shufflePick();
 REC.loop=!mix.sh;
 const sg0=MUS[mix.p],want=mix.on&&sg0&&sg0.rec&&!isMute();
 try{if(want){if(REC._k!==sg0){REC._k=sg0;REC.src=sg0.u?sg0.src:RECS[sg0.k];REC.currentTime=0}REC.volume=Math.min(1,Math.max(0,mix.m));if(REC.paused)REC.play().catch(()=>{})}else if(!REC.paused)REC.pause()}catch(e){}},200);
setInterval(()=>{
 if(!A||!mix.on)return;
 if(mix.am&&Date.now()-ms.lt>90000){const p=autoPick();if(p!==mix.p){mix.p=p;gramoRefresh()}ms.lt=Date.now()}
 const sg=MUS[mix.p];if(!sg||sg.g||sg.rec)return;const c=A.c,spb=60/sg.bpm/4;
 if(ms.p!==mix.p||ms.next<c.currentTime-.5){ms.p=mix.p;ms.step=0;ms.ji=0;ms.next=c.currentTime+.08}
 while(ms.next<c.currentTime+.3){const sw=(ms.step%2)?(sg.sw||0):0;seqStep(sg,ms.step,ms.next+sw,spb);ms.next+=spb;ms.step++}
},60);
function mus(i){audio();mix.p=i;mix.on=true;mix.am=false;ms.p=-1;gmT.p=-1;ms.st=Date.now();ms.dur=100000+Math.random()*100000;gramoRefresh()}
/* acak otomatis: ganti lagu secara acak, tidak ikut cuaca/waktu */
function shufflePick(){if(MUS.length<2)return;let i;do{i=Math.random()*MUS.length|0}while(i===mix.p);const sh=mix.sh;mus(i);mix.sh=sh}
function setShuffle(v){mix.sh=v;if(v){mix.am=false;ms.st=Date.now();ms.dur=100000+Math.random()*100000;if(!mix.on){audio();shufflePick()}}gramoRefresh()}
function mnext(d){mus((mix.p+d+MUS.length)%MUS.length)}
function gramoRefresh(){if($('m').style.display==='block'&&$('gr'))gramo()}
/* seek bar Gramofon: waktu berjalan / durasi */
const gmT={p:-1,t:0,l:Date.now(),d:0};
const gmF=s=>{s=Math.max(0,Math.floor(s||0));return(s/60|0)+':'+String(s%60).padStart(2,'0')};
function gmInfo(){const sg=MUS[mix.p];if(!sg)return{cur:0,dur:0,ok:0};
 if(sg.rec){const r=REC._k===sg?REC:null,d=r&&isFinite(r.duration)&&r.duration>0?r.duration:0;return{cur:r?r.currentTime:0,dur:d,ok:d>0}}
 return{cur:gmT.t,dur:mix.sh&&ms.dur?ms.dur/1000:0,ok:0}}
function gmPct(i){return i.dur?Math.min(1000,Math.round(i.cur/i.dur*1000)):0}
function gmHtml(){const i=gmInfo(),v=gmPct(i);
 return `<div class=gsk><span id=gtc>${gmF(i.cur)}</span><input type=range id=gsk min=0 max=1000 step=1 value=${v} style="--p:${v/10}%" ${i.ok?'':'disabled'} aria-label="Posisi lagu" oninput="gmMove(this)" onchange="gmSeek(this)" onpointerup="gmT.d=0" onpointercancel="gmT.d=0"><span id=gtd>${i.dur?gmF(i.dur):'--:--'}</span></div>`}
function gmMove(el){gmT.d=1;const i=gmInfo();el.style.setProperty('--p',el.value/10+'%');const c=$('gtc');if(c&&i.dur)c.textContent=gmF(el.value/1000*i.dur)}
function gmSeek(el){gmT.d=0;const i=gmInfo(),sg=MUS[mix.p];if(!sg||!sg.rec||!i.ok||REC._k!==sg)return;try{REC.currentTime=Math.min(i.dur-.05,el.value/1000*i.dur)}catch(e){}}
function gPlay(){if(mix.on){mix.on=false;gramoRefresh()}else mus(mix.p)}
setInterval(()=>{const n=Date.now(),dt=n-gmT.l;gmT.l=n;
 if(gmT.p!==mix.p){gmT.p=mix.p;gmT.t=0}else if(mix.on)gmT.t+=dt/1000;
 const el=$('gsk'),c=$('gtc'),d=$('gtd');if(!el||!c||!d||gmT.d)return;
 const i=gmInfo(),v=gmPct(i),a=gmF(i.cur),b=i.dur?gmF(i.dur):'--:--';
 if(el.disabled===!!i.ok)el.disabled=!i.ok;
 if(+el.value!==v){el.value=v;el.style.setProperty('--p',v/10+'%')}
 if(c.textContent!==a)c.textContent=a;if(d.textContent!==b)d.textContent=b},250);
var gmView='list';
function gramo(){
 if(gmView==='vinyl')return vinyl();
 if(gmView==='spotify')return spotify();
 const sl=(k,n,v)=>`<label>${n} <input type=range min=0 max=1 step=.05 value=${v} oninput="mix.${k}=+this.value;${k==='m'?'':'mix.au=false;$(\'au\').checked=false'}"></label>`;
 P(`<b id=gr>🎵 Gramofon</b><div style="margin:8px 0 10px"><button style="margin:0" onclick="gmView='vinyl';gramo()">💿 Vinyl Player</button><button style="margin:0 0 0 6px" onclick="gmView='spotify';gramo()">🎧 Spotify</button></div><small>${mix.on?'Memutar: <b>'+esc(MUS[mix.p].n)+'</b>':SPP?'Memutar: <b>Spotify</b>':'Berhenti'}</small><br>
 ${gmHtml()}<div class=gpc><button onclick="mnext(-1)" aria-label="Sebelumnya">⏮</button><button class=pp onclick="gPlay()" aria-label="${mix.on?'Jeda':'Putar'}">${mix.on?'⏸':'▶'}</button><button onclick="mnext(1)" aria-label="Berikutnya">⏭</button></div>
 <label><input type=checkbox ${mix.am?'checked':''} onchange="mix.am=this.checked;ms.lt=0;if(this.checked)mix.sh=false;gramoRefresh()"> Musik otomatis (ikut waktu & cuaca)</label>
 <button class="${mix.sh?'hot':''}" onclick="setShuffle(!mix.sh)">${IC.shuf}Acak otomatis: ${mix.sh?'nyala':'mati'}</button>
 ${MUS.map((m,i)=>m.u?'':`<button class="song ${mix.on&&mix.p===i?'hot':''}" onclick="mus(${i})">${mix.on&&mix.p===i?'▶ ':'♪ '}${esc(m.n)}</button>`).join('')}
 ${MUS.some(m=>m.u)?'<hr><b>Lagu tambahanmu</b>'+MUS.map((m,i)=>m.u?`<div class="ur"><button class="song ${mix.on&&mix.p===i?'hot':''}" onclick="mus(${i})">${mix.on&&mix.p===i?'▶ ':'♪ '}${esc(m.n)}</button><button class="${delAsk===m?'hot':''}" onclick="delClick(${i})">${IC.trash}${delAsk===m?'Yakin hapus?':'Hapus'}</button></div>`:'').join(''):''}<br>
 <button onclick="document.getElementById('upl').click()">${IC.plus}Tambah musik dari file</button><input type=file id=upl accept="audio/*,.mp3,.m4a,.aac,.ogg,.opus,.wav,.flac" multiple hidden onchange="addMusic(this.files)"><br><small>Tersimpan di peramban ini saja.</small><hr>
 ${sl('m','Musik',mix.m)}${sl('a','Api',mix.a)}${sl('h','Hujan',mix.h)}${sl('j','Jangkrik',mix.j)}${sl('w','Danau',mix.w)}<label><input type=checkbox id=au ${mix.au?'checked':''} onchange="mix.au=this.checked"> Suara alam ikut cuaca</label>`)}

/* ===== Tampilan baru: Vinyl Player (piringan hitam berputar mengikuti musik) ===== */
function vinyl(){
 const sg=MUS[mix.p],on=!!mix.on;
 P(`<div class=hd><button onclick="gmView='list';gramo()" aria-label="Kembali">↩ Kembali</button><b id=gr>💿 Vinyl Player</b></div>
 <div class=vp><div class=vw><div class=vdw><div class="vd${on?' on':''}"><div class=vl></div></div></div><div class=va id=vam style="transform:rotate(-2deg)"></div></div>
 <div class=vi><div class=vnt>${esc(sg?sg.n:'-')}</div><small>${on?'Memutar':'Jeda'}${mix.sh?' · Acak otomatis nyala':''}${mix.am?' · Ikut cuaca nyala':''}</small>${gmHtml()}<div class=gpc><button class="vsh${mix.am?' hot':''}" onclick="mix.am=!mix.am;ms.lt=0;if(mix.am)mix.sh=false;gramoRefresh()" aria-label="Otomatis ikut cuaca: ${mix.am?'nyala':'mati'}" title="Otomatis ikut waktu & cuaca">${IC.cloud}</button><button onclick="mnext(-1)" aria-label="Sebelumnya">⏮</button><button class=pp onclick="gPlay()" aria-label="${on?'Jeda':'Putar'}">${on?'⏸':'▶'}</button><button onclick="mnext(1)" aria-label="Berikutnya">⏭</button><button class="vsh${mix.sh?' hot':''}" onclick="setShuffle(!mix.sh)" aria-label="Acak otomatis: ${mix.sh?'nyala':'mati'}" title="Acak otomatis">${IC.shuf}</button></div></div></div>`);
 $('m').classList.add('wide');
 requestAnimationFrame(()=>requestAnimationFrame(vnArm))}
/* jarum: dari tepi luar piringan (awal lagu) bergeser ke tengah (akhir lagu); terangkat saat jeda */
function vnArm(){const a=$('vam');if(!a)return;let ang=-2;if(mix.on){const i=gmInfo();let p=i.dur?i.cur/i.dur:((i.cur%240)/240);p=Math.max(0,Math.min(1,p||0));ang=11.2+18.4*p}a.style.transform='rotate('+ang.toFixed(2)+'deg)'}
setInterval(vnArm,250);
/* musik mulai otomatis saat sentuhan pertama */
addEventListener('pointerdown',()=>{audio();mix.on=true;mix.am=true;mix.p=autoPick();ms.lt=Date.now()},{once:true,passive:true});


/* ===================== EKONOMI & TOKO ===================== */
S.coin=S.coin||0;
Object.assign(ITM,{
 beras:['Beras','🍚',1,'Bahan','Bahan dasar masakan hangat.'],
 sayur:['Sayur','🥬',1,'Bahan','Sayuran segar untuk direbus.'],
 telur:['Telur','🥚',1,'Bahan','Cocok dimasak bersama nasi.'],
 gula:['Gula','🍬',2,'Bahan','Pemanis untuk kue dan teh.'],
 nasi:['Nasi Telur','🍳',3,'Makanan','Mengenyangkan. Sudah pernah dinikmati sebanyak ini.'],
 rebus:['Sayur Rebus','🥗',3,'Makanan','Ringan dan menghangatkan. Sudah pernah dinikmati sebanyak ini.'],
 kue:['Kue Madu','🍰',4,'Makanan','Manis dan lembut. Sudah pernah dinikmati sebanyak ini.']
});
const SHOP={kayu:[2,10],umpan:[3,8],benih:[1,12],herb:[1,15],beras:[1,6],sayur:[1,5],telur:[1,7],gula:[1,9]};
const fprice=n=>{const f=FISH.find(a=>a[0]===n);return f?Math.max(5,Math.round(320/f[1])):5};
const RECIPE={nasi:{need:{beras:1,telur:1}},rebus:{need:{sayur:2}},kue:{need:{beras:1,gula:1,telur:1}}};
const coinUp=()=>{$('co').textContent='🪙 '+S.coin};setInterval(coinUp,300);coinUp();
function sellFish(n,q){q=Math.min(q,S.fish[n]||0);if(q<1)return;S.fish[n]-=q;const g=fprice(n)*q;S.coin+=g;save();toast('Terjual '+q+' × '+n+' · +🪙'+g);coinUp();$('m').style.display==='block'&&($('shp')?shop():bag())}
function buy(k,n){const [b,p]=SHOP[k],c=p*n;if(S.coin<c)return toast('Koin kurang 🪙');S.coin-=c;S.inv[k]=(S.inv[k]||0)+b*n;save();toast('Beli '+ITM[k][0]+' ×'+b*n);coinUp();shop()}
let SHT='Beli',SHS='kayu';
function shop(){
 const tabs=['Beli','Jual','Pet','Teman'].map(t=>`<button class="${SHT===t?'hot':''}" onclick="SHT='${t}';shop()">${t==='Beli'?'🛒 Beli':t==='Jual'?'🐟 Jual ikan':t==='Pet'?'🐾 Pet':'Teman'}</button>`).join('');
 let grid,det;
 if(SHT==='Teman'){const o=frShop();grid=o.grid;det=o.det}else if(SHT==='Pet'){
  const pk=Object.keys(PETS);if(!PETS[SHS])SHS=pk[0];const q=PETS[SHS],ow=S.pet.own[SHS],eq=S.pet.a===SHS;
  grid=pk.map(k=>slot(PETS[k].r,`<span class=ic><span class=pi>${pxSvg(PETS[k].ic)}</span></span>`,SHS===k,`SHS='${k}';shop()`,null,S.pet.own[k]?'Dimiliki':'🪙'+PETS[k].p.toLocaleString('id-ID'))).join('');
  det=`<div class=dt><div class=big><span class=pi>${pxSvg(q.ic)}</span></div><b>${q.n}</b><span class=str>${stars(q.r)}</span><small>${q.d}</small><hr>${ow?(eq?'<small>Sedang menemanimu</small>':`<div class=ba><button class=hot onclick="petUse('${SHS}')"><span>Pakai</span></button></div>`):`<div class=ba><button class=hot onclick="petBuy('${SHS}')"><span>Beli</span><span class=pr>🪙${q.p.toLocaleString('id-ID')}</span></button></div>`}</div>`;
 }else if(SHT==='Beli'){
  const ks=Object.keys(SHOP);
  grid=ks.map(k=>slot(ITM[k][2],`<span class=ic>${ITM[k][1]}</span>`,SHS===k,`SHS='${k}';shop()`,null,'🪙'+SHOP[k][1])).join('');
  const k=SHS in SHOP?SHS:ks[0],[b,p]=SHOP[k];
  det=`<div class=dt><div class=big>${ITM[k][1]}</div><b>${ITM[k][0]}</b><span class=str>${stars(ITM[k][2])}</span><small>Isi ×${b} · punya ×${S.inv[k]||0}</small><hr><small>${ITM[k][4]}</small><div class=ba><button class=hot onclick="buy('${k}',1)"><span>Beli</span><span class=pr>🪙${p}</span></button><button onclick="buy('${k}',5)"><span>Beli ×5</span><span class=pr>🪙${p*5}</span></button></div></div>`;
 }else{
  const fs=Object.keys(S.fish).filter(k=>S.fish[k]>0),tot=fs.reduce((a,k)=>a+fprice(k)*S.fish[k],0);
  if(!fs.includes(SHS))SHS=fs[0]||'';
  const cells=fs.map(k=>{const fi=FISH.find(a=>a[0]===k)||[k,20,'#999'];return slot(fishR(fi[1]),fsvg(fi[2],fi[1]<=8),SHS===k,`SHS='${k}';shop()`,S.fish[k],'🪙'+fprice(k))});
  for(let i=cells.length;i<8;i++)cells.push('<div class="sl em"></div>');grid=cells.join('');
  det=SHS?`<div class=dt><b>${SHS}</b><small>punya ×${S.fish[SHS]} · 🪙${fprice(SHS)}/ekor</small><div class=ba><button class=hot onclick="sellFish('${SHS}',1)"><span>Jual 1</span><span class=pr>🪙${fprice(SHS)}</span></button><button onclick="sellFish('${SHS}',${S.fish[SHS]})"><span>Jual ×${S.fish[SHS]}</span><span class=pr>🪙${fprice(SHS)*S.fish[SHS]}</span></button></div><hr><div class=ba><button onclick="Object.keys(S.fish).forEach(k=>sellFish(k,S.fish[k]))"><span>Jual semua ikan</span><span class=pr>🪙${tot}</span></button></div></div>`:'<div class=dt><small>Belum ada ikan. Pergi memancing dulu!</small></div>';
 }
 P(`<div class=hd><b id=shp>🛒 Toko</b><span class=cn>🪙 ${S.coin}</span><div class=tabs>${tabs}</div></div><div class=fx><div class=gd><div class=gi>${grid}</div></div><div class=pvw>${det}</div></div>`);
 $('m').classList.add('wide');if(SHT==='Teman')paintPV()}
$('sh').onclick=shop;

/* dapur: resep baru dari bahan toko */
function dapur2(){
 const rc=k=>Object.entries(RECIPE[k].need).map(([i,n])=>ITM[i][1]+'×'+n+'('+(S.inv[i]||0)+')').join(' ');
 P(`<b>Dapur</b><br>Herbal: ${S.inv.herb} · Ikan: ${fc()}<br><button onclick="cook('teh')">🍵 Teh herbal</button><button onclick="cook('sup')">🍲 Sup ikan</button><br>${Object.keys(RECIPE).map(k=>`<button onclick="cookN('${k}')">${ITM[k][1]} ${ITM[k][0]}</button><small>${rc(k)}</small><br>`).join('')}<small>Bahan bisa dibeli di 🛒 Toko. Makanan langsung dinikmati dan bikin hangat.</small>`)}
function cookN(k){const r=RECIPE[k];for(const i in r.need)if((S.inv[i]||0)<r.need[i])return toast('Bahan kurang — beli di toko 🛒');for(const i in r.need)S.inv[i]-=r.need[i];S.inv[k]=(S.inv[k]||0)+1;ch.pose='teh';T.cook=3500;T.buff=90000;X();toast(ITM[k][0]+' siap, hangat '+ITM[k][1]);save()}

/* ===== Layar penuh: skala mengikuti ukuran peta (rasio tetap, tanpa crop) ===== */
(function(){
const RW=1672,RH=941,w=document.getElementById('w'),bd=document.body;
function fit(){
 const cs=getComputedStyle(bd),vv=window.visualViewport;
 const pl=parseFloat(cs.paddingLeft)||0,pr=parseFloat(cs.paddingRight)||0,pt=parseFloat(cs.paddingTop)||0,pb=parseFloat(cs.paddingBottom)||0;
 const aw=Math.max(1,Math.min(bd.clientWidth,vv?vv.width:1e9)-pl-pr);
 const ah=Math.max(1,Math.min(bd.clientHeight,vv?vv.height:1e9)-pt-pb);
 const s=Math.min(aw/RW,ah/RH);
 w.style.setProperty('--gw',Math.floor(RW*s)+'px');
 w.style.setProperty('--gh',Math.floor(RH*s)+'px');
}
fit();
['resize','orientationchange','fullscreenchange'].forEach(e=>addEventListener(e,()=>{fit();setTimeout(fit,150);setTimeout(fit,500)}));
if(window.visualViewport)visualViewport.addEventListener('resize',fit);
if(window.ResizeObserver)new ResizeObserver(fit).observe(bd);
/* latar buram dari peta supaya sisi kosong tidak hitam polos */
const io=document.getElementById('io');
function bg(){try{const c=document.createElement('canvas');c.width=64;c.height=36;c.getContext('2d').drawImage(io,0,0,64,36);document.getElementById('bf').style.backgroundImage='url('+c.toDataURL()+')'}catch(e){}}
if(io.complete&&io.naturalWidth)bg();else io.addEventListener('load',bg,{once:true});
/* coba mode layar penuh saat sentuhan pertama */
addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')return;try{const d=document.documentElement;if(!document.fullscreenElement&&d.requestFullscreen){d.requestFullscreen({navigationUI:'hide'}).then(()=>{try{screen.orientation.lock('landscape').catch(()=>{})}catch(e){}}).catch(()=>{})}}catch(e){}},{once:true,passive:true});
})();

/* ===== layar penuh manual + mode desktop ===== */
(function(){const de=document.documentElement,b=document.getElementById('fsb');
 const isFs=()=>!!(document.fullscreenElement||document.webkitFullscreenElement);
 function tog(){try{if(isFs()){(document.exitFullscreen||document.webkitExitFullscreen).call(document)}else{const r=de.requestFullscreen||de.webkitRequestFullscreen;if(r)r.call(de,{navigationUI:'hide'})}}catch(e){}}
 function lab(){const f=isFs(),l=f?'Keluar layar penuh':'Layar penuh';b.dataset.l=l;b.setAttribute('aria-label',l);b.title=l+' (F11 / F)'}
 if(!(de.requestFullscreen||de.webkitRequestFullscreen))b.style.display='none';
 b.onclick=tog;['fullscreenchange','webkitfullscreenchange'].forEach(e=>document.addEventListener(e,lab));
 addEventListener('keydown',e=>{if(e.key!=='f'&&e.key!=='F')return;if(e.ctrlKey||e.metaKey||e.altKey||e.repeat)return;const n=(e.target.tagName||'').toUpperCase();if(n==='INPUT'||n==='TEXTAREA'||e.target.isContentEditable)return;tog()});
 try{if(matchMedia('(hover:hover) and (pointer:fine)').matches){de.classList.add('dk');
  addEventListener('pointerdown',e=>{if(e.pointerType==='touch')de.classList.remove('dk')},{passive:true});
  let seen=0;try{seen=localStorage.getItem('pondok_hint')}catch(e){}
  if(!seen)setTimeout(()=>{try{toast('WASD / panah: jalan · E / Enter: aksi · F: layar penuh');localStorage.setItem('pondok_hint','1')}catch(e){}},3500)}}catch(e){}
})();

/* ===================== TEMAN SEKAMAR ===================== */
const FRP=12000,FRROLE={teman:'Teman',istri:'Istri',suami:'Suami'};
const FRDEF={f:{n:'Rina',h:3,s:'side'},m:{n:'Dimas',h:0,s:'messy'}};
const FR={mode:'idle',t:1500,tx:0,ty:0,next:null,spot:null,seat:null,sn:null,sb:0,lb:0,lie:0,walk:0,react:0,pose:'berdiri',inT:0,outT:0,last:'',dx:0,dy:0,ds:4,ph:'',pt:0,lit:0,say:''};
const FRPOSE={bangku:'teh',meja:'menulis',kursi:'teh',rak:'membaca',dapur:'teh',dermaga:'memancing',lentera:'lentera'};
const FRDUR={bangku:[3e4,6e4],meja:[25e3,50e3],kursi:[25e3,55e3],rak:[15e3,35e3],dapur:[9e3,16e3],jendela:[7e3,14e3],gramofon:[8e3,14e3],api:[8e3,14e3],dermaga:[30e3,70e3],lentera:[4e3,6e3],kebun:[7e3,13e3]};
const FRL={
 teman:{d:['Hai! Lagi santai?','Sini, ngobrol dulu.','Hari ini enak ya.','Aku jagain rumah, tenang aja.'],n:['Ngantuk nih…','Sudah malam, istirahat yuk.']},
 istri:{d:['Selamat datang, sayang.','Sudah makan belum?','Aku senang kamu di rumah.','Jangan kecapekan ya.'],n:['Sudah malam, sayang. Tidur yuk.','Aku ngantuk… temani aku?']},
 suami:{d:['Selamat datang, sayang.','Capek? Istirahat dulu ya.','Aku di sini kok.','Nanti kita masak bareng?'],n:['Sudah malam, sayang. Tidur yuk.','Besok kita lanjut ya.']}
};
const spotOf=n=>OUTS.find(a=>a[0]===n)||INS.find(a=>a[0]===n)||(window.BKS&&BKS.find(a=>a[0]===n));
const okS=(sc,x,y)=>sc==='kedai'?pip(x,y,window.KWALK):sc==='bukit'?pip(x,y,BWALK):sc==='luar'?pip(x,y,WALK):!(x<90||x>1590||y<690||y>880||BLK.some(r=>x>r[0]-30&&x<r[0]+r[2]+30&&y>r[1]-30&&y<r[1]+r[3]+30));
const frNm=()=>S.fr?(S.fr.name||FRDEF[S.fr.g].n):'';
const okGf=it=>!it||it.g==='u'||it.g===S.fr.g;
function frReset(){Object.assign(FR,{call:0,ct:0,mode:'idle',t:1500,next:null,spot:null,seat:null,sb:0,lb:0,lie:0,walk:0,react:0,pose:'berdiri',inT:0,outT:0,last:'',ph:'',pt:0,lit:0,say:''})}
function frEnsure(){const s=S.fr;if(s.x==null||s.y==null){s.sc='dalam';s.x=900+rn(-40,40);s.y=800}if(!s.f)s.f={o:'auto',h:FRDEF[s.g].h,s:FRDEF[s.g].s,hat:'auto',acc:''};if(!s.role)s.role='teman'}
function frAvail(n){const s=S.fr;if(n==='bangku'&&FR.call)return true;if(s.sc!==SCA())return true;const sp=spotOf(n);if(!sp)return false;
 if(n==='kasur'&&(ch.lie||ch.lb>0))return true;
 if(ch.sit===n)return false;
 if(Math.hypot(ch.x-sp[5],ch.y-sp[6])<64)return false;
 if(ch.act&&Math.abs(ch.tx-sp[5])<2&&Math.abs(ch.ty-sp[6])<2)return false;
 return true}
function frRel(){FR.call=0;FR.last=FR.spot||FR.last;FR.spot=null;FR.seat=null;FR.lie=0;FR.ph='';FR.lit=0;FR.pose='berdiri';FR.mode='idle';FR.next=null;FR.t=rn(1800,4500)}
function frWander(a,b){const s=S.fr;a=a||80;b=b||260;for(let i=0;i<14;i++){const r=Math.random()*6.283,d=rn(a,b),x=s.x+Math.cos(r)*d,y=s.y+Math.sin(r)*d*.6;if(okS(s.sc,x,y)){FR.tx=x;FR.ty=y;FR.next=null;FR.mode='walk';return true}}return false}
function frGo(n){const sp=spotOf(n);FR.next=n;FR.tx=sp[5];FR.ty=sp[6];FR.mode='walk'}
function frPick(){const s=S.fr,h=S.m/60,night=h>=22||h<6,bad=S.w==='badai'||S.w==='hujan',o=[],add=(w,f)=>{if(w>0)o.push([w,f])};
 if(s.sc==='dalam'){
  if(S.fire<=0&&(night||bad||S.se==3||h>=18)&&frAvail('api')){frGo('api');return}
  if(night&&frAvail('kasur')){frGo('kasur');return}
  const W={meja:3,kursi:3,rak:3,dapur:1.4,jendela:1,gramofon:1,api:(S.se==3||S.fire>0)?1.5:.4};
  Object.keys(W).forEach(k=>{if(k!==FR.last&&frAvail(k))add(W[k],()=>frGo(k))});
  add(1.6,()=>{if(!frWander())FR.t=2500});
  if(!night&&!bad&&FR.inT>45e3)add(.7,()=>{FR.next='out';FR.tx=700;FR.ty=770;FR.mode='walk'});
 }else{
  if(s.sc==='bukit'){frPickBk(night,bad);return}
   if(night||bad||FR.outT>75e3){const d=spotOf('pintu');FR.next='in';FR.tx=d[5];FR.ty=d[6];FR.mode='walk';return}
  const W={dermaga:3,lentera:T.nfv>.3?3:.5,kebun:2};
  Object.keys(W).forEach(k=>{if(k!==FR.last&&frAvail(k))add(W[k],()=>frGo(k))});
  add(1.5,()=>{if(!frWander())FR.t=2500});
  if(!S.bk||true)add(S.bk?6:1.8,()=>{const d=spotOf('gerbang');FR.next='bukit';FR.tx=d[5];FR.ty=d[6];FR.mode='walk'});
   add(2+FR.outT/15e3,()=>{const d=spotOf('pintu');FR.next='in';FR.tx=d[5];FR.ty=d[6];FR.mode='walk'});
 }
 let r=Math.random()*o.reduce((a,b)=>a+b[0],0);for(const q of o){r-=q[0];if(r<=0){q[1]();return}}FR.t=2000}
function frPickBk(night,bad){const o=[],add=(w,f)=>{if(w>0)o.push([w,f])};
  const back=()=>{const d=spotOf('keluar');FR.next='back';FR.tx=d[5];FR.ty=d[6];FR.mode='walk'};
  if(night||bad||FR.outT>70e3){back();return}
  if(FR.last!=='bangku'&&frAvail('bangku'))add(3,()=>frGo('bangku'));
  add(2,()=>{if(!frWander())FR.t=2500});add(.8+FR.outT/3e4,back);
  let r=Math.random()*o.reduce((a,b)=>a+b[0],0);for(const q of o){r-=q[0];if(r<=0){q[1]();return}}FR.t=2000}
function frArrive(){const s=S.fr,n=FR.next;FR.next=null;
  if(n==='bukit'){s.sc='bukit';s.x=760+rn(-30,30);s.y=885;FR.outT=0;FR.mode='idle';FR.t=rn(1200,2500);return}
  if(n==='back'){s.sc='luar';s.x=250+rn(-14,14);s.y=436+rn(8,24);FR.outT=0;FR.mode='idle';FR.t=rn(1200,2500);return}
 if(n==='out'){s.sc='luar';s.x=632+rn(-24,24);s.y=505+rn(8,28);FR.outT=0;FR.mode='idle';FR.t=rn(1200,2500);return}
 if(n==='in'){s.sc='dalam';s.x=700+rn(-30,30);s.y=770+rn(-10,10);FR.inT=0;FR.mode='idle';FR.t=rn(1200,2500);return}
 if(n&&spotOf(n)){
  if(!frAvail(n)){FR.mode='idle';FR.t=rn(1500,3000);return}
  const d=FRDUR[n];FR.spot=n;FR.mode='do';FR.t=n==='kasur'?1e9:rn(d[0],d[1]);FR.pose=FRPOSE[n]||'berdiri';
  if(SEAT[n]){FR.seat=n;FR.sn=n}
  if(n==='bangku'&&FR.call){FR.t=1e9;FR.react=2600;const q=FRSIT[s.role]||FRSIT.teman;toast(frNm()+': “'+q+'”')}
  if(n==='kasur'){FR.lie=1;FR.ph='sleep';FR.pt=rn(22e3,45e3)}
  if(n==='api'&&S.fire<=0){FR.lit=1;FR.t=rn(3200,4200);FR.pose='berdiri'}
  if(n==='lentera'&&T.nfv>.3)S.lamp=1;
  return}
 FR.mode='idle';FR.t=rn(1500,4000)}
function frLight(){const cold=S.se==3&&S.fire<=0;if(S.inv.kayu>0)S.inv.kayu--;S.fire+=600;if(cold)T.warm=9000;save();toast(frNm()+' menyalakan api unggun 🔥')}
const BEDSEP=30;
const FRSAY=['Hoaam…','Hmm… masih malam.','*mengucek mata*','Eh, sudah bangun?'];
/* pemain mau pakai tempat yang sedang dipakai teman -> teman berdiri & memberi jalan */
function frYield(n,sc){const s=S.fr;if(!s||!s.g||s.sc!==sc||n==='kasur')return;
 if(FR.spot===n||(FR.mode==='walk'&&FR.next===n)){frRel();if(!frWander(90,200))FR.t=800}}
function updFr(dt){bkEase(dt);const s=S.fr;if(!s||!s.g)return;frEnsure();bkCall(dt,s);
 FR.react=Math.max(0,FR.react-dt);
 {const k=1-Math.exp(-dt/300),pl=ch.lie||ch.lb>.3,fl=FR.lie||FR.lb>.3;FR.so=(FR.so||0)+((pl&&fl?-BEDSEP:0)-(FR.so||0))*k;ch.so=(ch.so||0)+((pl&&fl?BEDSEP:0)-(ch.so||0))*k;
  if(ch.lie&&FR.spot==='kasur'&&FR.mode==='do'){FR.lie=1;if(FR.ph!=='sleep'){FR.ph='sleep'}FR.pt=Math.max(FR.pt,4000)}}
 FR.sb=cl(FR.sb+(FR.seat?dt:-dt)/420,0,1);FR.lb=cl(FR.lb+(FR.lie?dt:-dt)/700,0,1);
 if(s.sc==='dalam')FR.inT+=dt;else FR.outT+=dt;
 const h=S.m/60,night=h>=22||h<6;
 if(FR.mode==='walk'){
  if(FR.sb>0||FR.lb>0){FR.walk=0;return}
  const dx=FR.tx-s.x,dy=FR.ty-s.y,d=Math.hypot(dx,dy);
  if(d>3){const w=s.sc==='kedai'?[FR.tx,FR.ty]:nextT(FR,s.x,s.y,FR.tx,FR.ty),wx=w[0]-s.x,wy=w[1]-s.y,wd=Math.hypot(wx,wy)||1,v=Math.min(wd,dt*.17);{const nx=s.x+wx/wd*v,ny=s.y+wy/wd*v;if(s.sc==='kedai'||s.sc!=='bukit'||okS('bukit',nx,ny)){s.x=nx;s.y=ny}else{const cx=700-s.x,cy=800-s.y,cd=Math.hypot(cx,cy)||1;s.x+=cx/cd*v;s.y+=cy/cd*v}}FR.walk=1}else{FR.walk=0;frArrive()}
 }else{
  FR.walk=0;FR.t-=dt;
  if(FR.mode==='do'){if(FR.spot==='kasur'){if(!night)frRel();else{FR.pt-=dt;
   if(FR.ph==='sleep'&&FR.pt<=0){FR.ph='wake';FR.lie=0;FR.pt=rn(5e3,9e3);FR.say=FRSAY[Math.random()*FRSAY.length|0]}
   else if(FR.ph==='wake'&&FR.pt<=0){if(S.fire<=0&&frAvail('api')){frRel();frGo('api')}else{FR.ph='sleep';FR.lie=1;FR.pt=rn(22e3,45e3)}}}}
  else if(FR.t<=0){if(FR.spot==='api'&&FR.lit&&S.fire<=0)frLight();frRel()}}
  else if(FR.t<=0)frPick()}}
/* gambar */
const fcv=document.createElement('canvas');fcv.width=40;fcv.height=42;const fcx=fcv.getContext('2d');
const fst={blink:false,gx:0,gy:0};let fnb=1500,fbu=0,fng=2000;
function frLook(){const F=S.fr.f,o=(F.o!=='auto'&&SEASONS[F.o])?F.o:SK[S.se];fst.season=o;fst.hat=(!F.hat||F.hat==='auto')?o:F.hat;fst.hair=HAIRS[F.h]?F.h:0;fst.hairStyle=HAIR_STYLES[F.s]?F.s:'messy';fst.acc=F.acc||'';fst.g=S.fr.g}
function frExpr(){const h=S.m/60;
 if(FR.lie||FR.lb>.3)return'mengantuk';
 if(T.thun>0)return'takut';
 if(frListen())return'hangat';
 if(FR.react>0)return S.fr.role==='teman'?'senang':'tersipu';
 if(FR.spot==='meja')return'berpikir';
 if(FR.spot==='api'||FR.spot==='gramofon')return'hangat';
 if(S.se==3&&FR.spot!=='api'&&(S.fr.sc!=='dalam'||S.fire<=0))return'dingin';
 if(h>=22||h<5)return'mengantuk';
 return'biasa'}
function frDrawCh(t,x,y,sc,pose,sit,rot){
 if(t>fnb){fbu=t+140;fnb=t+rn(2600,5800)}fst.blink=t<fbu;
 if(t>fng){fst.gx=[-1,0,0,1][Math.random()*4|0];fst.gy=Math.random()<.2?1:0;fng=t+rn(1400,3800)}
 fst.wp=(FR.walk&&!sit&&!rot)?t/110:0;{const L=lgt();fst.vl=L.d;fst.vr=L.r;if(!sit&&!rot){const bb=FR.walk?Math.abs(Math.sin(t/110))*(S.scene==='dalam'?5:4):0;gshadow(x,y-bb,sc,.4,L.d)}}frLook();fst.expr=frExpr();fst.pose=pose||'berdiri';render(fcx,fst,t,true);g.imageSmoothingEnabled=false;
 if(rot){g.save();g.translate(x,y);g.rotate(rot);g.drawImage(fcv,-20*sc,-21*sc,40*sc,42*sc);g.restore()}
 else if(sit){g.save();g.beginPath();g.rect(x-20*sc,y-33*sc,40*sc,33*sc);g.clip();g.drawImage(fcv,x-20*sc,y-33*sc,40*sc,42*sc);g.restore()}
 else g.drawImage(fcv,x-20*sc,y-37*sc,40*sc,42*sc)}
function frFish(t,cx,cy,sc){const rx=cx+18.5*sc,ry=cy-22*sc,tx=rx+26,ty=ry-30,px=cx+172,py=cy+42+Math.sin(t/650)*2,dip=Math.sin(t/2300)>.93?5:0;
 g.strokeStyle='#7a4a2a';g.lineWidth=4;g.beginPath();g.moveTo(rx,ry);g.lineTo(tx,ty);g.stroke();
 g.strokeStyle='rgba(235,240,250,.9)';g.lineWidth=2;g.beginPath();g.moveTo(tx,ty);g.quadraticCurveTo((tx+px)/2,(ty+py)/2+28,px,py+dip);g.stroke();
 const k=(t/700)%1;g.strokeStyle='rgba(255,255,255,'+(1-k)*.6+')';g.lineWidth=2;g.beginPath();g.ellipse(px,py+dip+4,12+k*16,4+k*5,0,0,7);g.stroke();
 g.fillStyle='#e84a4a';g.beginPath();g.arc(px,py+dip,8,Math.PI,0);g.fill();g.fillStyle='#fff';g.beginPath();g.arc(px,py+dip,8,0,Math.PI);g.fill()}
function drawFr(t,pass){const s=S.fr;if(!s||!s.g||s.sc!==SCA())return;
 const both=S.scene==='dalam'&&FR.lb>0&&(ch.lie||ch.lb>0);
 const bkDuo=s.sc==='bukit'&&FR.seat==='bangku'&&ch.sit==='bangku';
 if((both||bkDuo?true:s.y<=ch.y)!==(pass===0))return;
 if(s.sc==='bukit'){frDrawBk(t,s);return}
  const out=s.sc==='luar',sc=out?4:6,cx=s.x,cy=s.y+(FR.walk?Math.abs(Math.sin(t/110))*(out?4:5):0);
 if(!out&&FR.lb>0){const u=ez(FR.lb),L=LIE;FR.dx=mv(cx,L.x,u);FR.dy=mv(cy,L.y,u);FR.ds=mv(6,L.sc,u);
  FR.ds=FR.ds*(1-.15*Math.abs(FR.so||0)/BEDSEP);frDrawCh(t,FR.dx,mv(cy-96,L.y+Math.sin(t/700)*2*u+(FR.so||0)*u,u),FR.ds,'berdiri',0,L.rot*u);drawOv('kasur',ez(cl((FR.lb-.45)/.55,0,1)));
  if(FR.lb>.8&&!(ch.lie&&ch.lb>.8))zzz(t)}
 else if(!out&&FR.sb>0&&SEAT[FR.sn]){const u=ez(FR.sb),Z=SEAT[FR.sn],sx=Z.x+Math.sin(t/500)*Z.sw;FR.dx=mv(cx,sx,u);FR.dy=mv(cy,Z.y,u);FR.ds=mv(6,Z.sc,u);
  frDrawCh(t,FR.dx,FR.dy,FR.ds,FR.pose,u>.5);drawOv(FR.sn,ez(cl((FR.sb-.3)/.7,0,1)))}
 else{FR.dx=cx;FR.dy=cy;FR.ds=sc;frDrawCh(t,cx,cy,sc,FR.pose);
  
  if(!out&&FR.spot==='api'&&FR.lit&&FR.mode==='do'){g.save();for(let i=0;i<7;i++){const p=(t/450+i/7)%1;g.globalAlpha=1-p;g.fillStyle=i%2?'#ffcf5a':'#ff8a3a';g.fillRect(195+Math.sin(i*2.3)*26,570-p*60,6,6)}g.restore()}
 if(out&&FR.spot==='dermaga'&&FR.mode==='do')frFish(t,cx,cy,sc)}}
function frDrawBk(t,s){const Z=SEAT.bangku,cy0=s.y+(FR.walk?Math.abs(Math.sin(t/110))*4:0);
  if(FR.sb>0&&FR.sn==='bangku'){const u=ez(FR.sb),sc=mv(BKSC(s.y),Z.sc,u),X=mv(s.x,Z.x+BK2.f,u),Y=mv(cy0,Z.y,u);FR.dx=X;FR.dy=Y;FR.ds=sc;
   if(u>.5){frDrawCh(t,X,-30000,sc,FR.pose,1);g.save();g.beginPath();g.rect(X-34*sc,Y-60*sc,68*sc,60*sc);g.clip();g.imageSmoothingEnabled=false;const HF=frListen()?Math.sin(t/500)*.07:0;/* fase sama dengan pemain: goyang serempak */
    if(HF){const R0=23,px=16,OV=8,sx=X-20*sc,sy=Y-33*sc,sag=Math.abs(HF)*6*sc;g.drawImage(fcv,0,R0-OV,40,42-(R0-OV),sx,sy+(R0-OV)*sc,40*sc,(42-(R0-OV))*sc);g.save();g.translate(sx+px*sc,sy+R0*sc+sag);g.rotate(HF);g.drawImage(fcv,0,0,40,R0+4,-px*sc,-R0*sc,40*sc,(R0+4)*sc);g.restore()}
    else g.drawImage(fcv,X-20*sc,Y-33*sc,40*sc,42*sc);g.restore();window.bkFront&&bkFront()}
   else frDrawCh(t,X,Y,sc,FR.pose,0)}
  else{const sc=BKSC(s.y);FR.dx=s.x;FR.dy=cy0;FR.ds=sc;frDrawCh(t,s.x,cy0,sc,FR.pose)}}
/* ===== duduk berdua di bangku bukit ===== */
function frListen(){const s=S.fr;return !!(s&&s.g&&s.sc==='bukit'&&S.bk&&FR.seat==='bangku'&&FR.sb>.9&&!FR.lie&&(mix.on||SPP)&&!isMute())}
const BKSH=31,BK2={p:0,f:0,h:0};
const FRCALL={teman:['Oke, aku ke sana!','Sebentar ya!'],istri:['Iya sayang, aku ke sana.','Tunggu ya, sayang.'],suami:['Iya sayang, aku ke sana.','Tunggu ya, sayang.']};
const FRSIT={teman:'Duduk berdua begini enak ya.',istri:'Duduk dekat kamu begini… nyaman.',suami:'Duduk dekat kamu begini… nyaman.'};
/* geser halus: pemain ke kiri, teman ke kanan saat berdua; balik ke tengah kalau sendirian */
function bkEase(dt){const s=S.fr,ok=!!(s&&s.g&&s.sc==='bukit'),pS=!!(S.bk&&ch.sit==='bangku'),fS=ok&&FR.seat==='bangku',fA=ok&&!!FR.call&&FR.mode==='walk'&&FR.next==='bangku'&&Math.hypot(s.x-(388+BKSH),s.y-606)<110,pr=pS&&(fS||fA),k=1-Math.exp(-dt/220);
 BK2.p+=((pr?-BKSH:0)-BK2.p)*k;BK2.f+=((pr?BKSH:0)-BK2.f)*k}
/* teman yang dipanggil menunggu selama pemain duduk, berdiri lagi setelah pemain bangun */
function bkCall(dt,s){
 if(!FR.call){FR.ct=0;return}
 if(!((S.bk&&ch.sit==='bangku')||(S.kd&&/^kdbangku/.test(ch.sit||'')))){FR.call=0;if(FR.mode==='do'&&(FR.spot==='bangku'||/^kdbangku/.test(FR.spot||'')))FR.t=rn(1200,2600);else if(FR.mode==='walk'&&(FR.next==='bangku'||/^kdbangku/.test(FR.next||''))){FR.next=null;FR.mode='idle';FR.t=rn(1200,2500)}return}
 if(FR.mode==='walk'){FR.ct=(FR.ct||0)+dt;if(FR.ct>16000){s.x=FR.tx;s.y=FR.ty}}else FR.ct=0;
 if(FR.mode==='do'&&(FR.spot==='bangku'||/^kdbangku/.test(FR.spot||'')))FR.t=Math.max(FR.t,4000)}
function callFr(){if(S.kd&&window.kdCall)return kdCall();const s=S.fr;if(!s||!s.g||!S.bk||ch.sit!=='bangku')return;frEnsure();
 if(FR.call)return;
 if(s.sc==='bukit'&&FR.seat==='bangku'&&FR.mode==='do')return;
 if(FR.lie||FR.lb>.3){toast(frNm()+' sedang tidur… zzz');return}
 frRel();
 if(s.sc!=='bukit'){s.sc='bukit';s.x=760+rn(-30,30);s.y=885;FR.sb=0;FR.outT=0}
 FR.call=1;FR.ct=0;FR.next='bangku';FR.tx=388+BKSH;FR.ty=606;FR.mode='walk';
 const L=FRCALL[s.role]||FRCALL.teman;toast(frNm()+': “'+L[Math.random()*L.length|0]+'”')}
$('cl').onclick=()=>{audio();callFr()};
setInterval(()=>{const b=$('cl'),s=S.fr,at=!!(s&&s.g&&((S.bk&&ch.sit==='bangku')||(S.kd&&/^kdbangku/.test(ch.sit||'')))&&ch.sb>.6),sitting=!!(s&&((s.sc==='bukit'&&FR.seat==='bangku')||(s.sc==='kedai'&&/^kdbangku/.test(FR.seat||'')))&&FR.mode==='do'),ok=at&&!sitting&&!FR.call;b.style.display=ok?'block':'none';if(ok){setIc(b,'duo','Panggil '+frNm()+' duduk berdua');b.className='hot'}},250);
/* ketuk teman */
function frTap(x,y){const s=S.fr;if(!s||!s.g||s.sc!==SCA())return false;
 if(Math.abs(x-FR.dx)<22*FR.ds&&y>FR.dy-37*FR.ds&&y<FR.dy+8){
  const h=S.m/60,night=h>=22||h<5,L=FRL[s.role]||FRL.teman,nm=frNm();
  if(FR.lie||FR.lb>.5){toast(nm+' sedang tidur… zzz');return true}
  FR.react=2400;const a=night?L.n:L.d;toast(nm+': “'+a[Math.random()*a.length|0]+'”');return true}
 return false}
/* beli & atur */
function frBuy(g){if(S.frs[g])return toast('Kamu sudah punya teman ini');
 if((S.coin||0)<FRP)return toast('Koin kurang 🪙 Butuh '+FRP.toLocaleString('id-ID'));
 const d=FRDEF[g];S.coin-=FRP;S.fr=S.frs[g]={g,name:d.n,role:'teman',f:{o:'auto',h:d.h,s:d.s,hat:'auto',acc:''},sc:'dalam',x:900,y:800};frReset();save();coinUp();toast(d.n+' pindah jadi teman sekamarmu!');shop()}
function frUse(g){const o=S.frs[g];if(!o)return;S.fr=o;o.sc='dalam';o.x=900+rn(-40,40);o.y=800;frReset();save();toast(frNm()+' aktif jadi teman sekamarmu');$('shp')?shop():frPanel()}
function frOff(){if(!S.fr)return;const n=frNm();S.fr=null;frReset();save();toast(n+' dinonaktifkan');$('shp')?shop():frPanel()}
function frShop(){const s=S.fr,ks=['f','m'],nm={f:'Teman Cewek',m:'Teman Cowok'};if(!ks.includes(SHS))SHS='f';
 const grid=ks.map(k=>slot(3,pvc('semi','none',FRDEF[k].h,FRDEF[k].s,'',k),SHS===k,`SHS='${k}';shop()`,null,s&&s.g===k?'Aktif':S.frs[k]?'Dimiliki':'🪙'+FRP.toLocaleString('id-ID'),!!S.frs[k])).join('');
 const q=SHS,d=FRDEF[q];let act;
 if(s&&s.g===q)act='<small>Aktif jadi teman sekamarmu</small><div class=ba><button class=hot onclick="frPanel()"><span>Atur teman</span></button><button onclick="frOff()"><span>Nonaktifkan</span></button></div>';
 else if(S.frs[q])act=`<small>${s?'Kamu hanya bisa punya 1 teman aktif. Memakai dia akan menonaktifkan '+frNm()+'.':'Dimiliki, sedang nonaktif.'}</small><div class=ba><button class=hot onclick="frUse('${q}')"><span>Pakai</span></button></div>`;
 else act=`<div class=ba><button class=hot onclick="frBuy('${q}')"><span>Beli</span><span class=pr>🪙${FRP.toLocaleString('id-ID')}</span></button></div>`;
 const det=`<div class=dt><canvas class=pv width=40 height=42 data-o=semi data-hat=none data-hr=${d.h} data-s=${d.s} data-acc="" data-g=${q} style="width:100%;max-width:120px;height:auto;aspect-ratio:40/42;flex:none;image-rendering:pixelated;display:block;background:#e8dcc0;border:3px solid #3a2535;border-radius:8px"></canvas><b>${nm[q]}</b><span class=str>${stars(3)}</span><small>Teman sekamar yang bergerak sendiri: duduk, baca, menulis, dan keluar rumah. Lebih suka di rumah. Bisa diberi nama, peran (${q==='f'?'teman / istri':'teman / suami'}) dan baju dari koleksimu.</small><hr>${act}</div>`;
 return{grid,det}}
let FRT='info',FRC=0;
function frSet(k,v){S.fr.f[k]=v;save();frPanel()}
function frTab(k){FRT=k;FRC=0;frPanel()}
function frRole(r){S.fr.role=r;save();toast(frNm()+' sekarang berperan jadi '+FRROLE[r].toLowerCase());frPanel()}
function frSaveName(){const i=$('frn'),v=cleanName(i?i.value:'');S.fr.name=v;save();toast('Namanya sekarang '+frNm());frPanel()}
function frPanel(){const s=S.fr;
 if(!s){const ks=Object.keys(S.frs);P('<div class=hd><b>Teman</b></div><div class=bd>'+(ks.length?ks.map(k=>`<button class=song onclick="frUse('${k}')">${S.frs[k].name||FRDEF[k].n} · nonaktif (ketuk untuk pakai)</button>`).join('')+'<small>Hanya 1 teman yang bisa aktif.</small>':'<small>Belum punya teman sekamar. Beli di 🛒 Toko, tab Teman.</small>')+'</div>');$('m').classList.add('wide');return}
 frEnsure();
 const F=s.f,g=s.g,acc=F.acc||'',o=(F.o!=='auto'&&SEASONS[F.o])?F.o:SK[S.se],cur=(!F.hat||F.hat==='auto')?o:F.hat;
 const tab=(k,l)=>`<button class="${FRT===k?'hot':''}" onclick="frTab('${k}')">${l}</button>`;
 let body;
 if(FRT==='info'){
  const roles=g==='f'?['teman','istri']:['teman','suami'];
  body=`<div class=bd><div class=row><span class=rl>Nama</span><div class=rcr style="flex:1"><input type=text id=frn maxlength=${NAME_MAX} dir=ltr autocomplete=off autocorrect=off autocapitalize=words spellcheck=false style="direction:ltr;unicode-bidi:isolate;text-align:left" placeholder="${FRDEF[g].n}"><button onclick="frSaveName()">Simpan</button></div></div><div class=row><span class=rl>Peran</span><div class=tabs>${roles.map(r=>`<button class="${s.role===r?'hot':''}" onclick="frRole('${r}')">${FRROLE[r]}</button>`).join('')}</div></div><hr><small>Dia bergerak sendiri: duduk, baca, menulis, memancing, dan lebih suka di rumah. Kalau kamu mau pakai tempat yang sedang dipakainya, dia otomatis berdiri dan memberi jalan. Bajunya diambil dari koleksimu.</small><hr><div class=ba><button onclick="frOff()">Nonaktifkan</button>${Object.keys(S.frs).filter(k=>k!==g).map(k=>`<button onclick="frUse('${k}')">Ganti ke ${S.frs[k].name||FRDEF[k].n}</button>`).join('')}</div></div>`;
 }else if(FRT==='baju'){
  const ks=['auto',...Object.keys(SEASONS).filter(k=>!SEASONS[k].x&&(!SEASONS[k].g||SEASONS[k].g===g)),...Object.keys(SEASONS).filter(k=>SEASONS[k].x&&own('o:'+k)&&okGf(GIM['o:'+k]))];
  body='<div class=gi>'+ks.map(k=>{const real=k==='auto'?SK[S.se]:k,on=F.o===k||(!SEASONS[F.o]&&k==='auto');return slot(k==='auto'?1:(RAR[k]||(GIM['o:'+k]||{}).r||1),pvc(real,cur,F.h,F.s,acc,g),on,`frSet('o','${k}')`,null,k==='auto'?'Otomatis':SEASONS[k].n,on)}).join('')+'</div>';
 }else if(FRT==='topi'){
  body='<div class=gi>'+HATS.map(([k,n,r])=>{const on=(F.hat||'auto')===k;return slot(r,pvc(o,k==='auto'?o:k,F.h,F.s,acc,g),on,`frSet('hat','${k}')`,null,n,on)}).join('')+'</div>';
 }else if(FRT==='rambut'){
  body='<div class=gi>'+HAIRS.map((h,i)=>({h,i})).filter(q=>!q.h.x||own('c:'+q.i)).map(({h,i})=>slot((GIM['c:'+i]||{}).r||2,`<div class=sw style="background:${h.c}"></div>`,F.h===i,`frSet('h',${i})`,null,h.n,F.h===i)).join('')+
   Object.keys(HAIR_STYLES).filter(k=>HAIR_STYLES[k].x?(own('s:'+k)&&okGf(GIM['s:'+k])):(!HAIR_STYLES[k].g||HAIR_STYLES[k].g===g)).map(k=>{const on=F.s===k;return slot((GIM['s:'+k]||{}).r||3,pvc(o,cur,F.h,k,acc,g),on,`frSet('s','${k}')`,null,HAIR_STYLES[k].n,on)}).join('')+'</div>';
 }else{
  body='<div class=gi>'+['none',...ACCS.filter(k=>own('a:'+k)&&okGf(GIM['a:'+k]))].map(k=>{const on=acc===k||(k==='none'&&!acc);return slot(k==='none'?1:GIM['a:'+k].r,pvc(o,'none',F.h,F.s,k==='none'?'':k,g),on,`frSet('acc','${k==='none'?'':k}')`,null,k==='none'?'Tanpa':GIM['a:'+k].n,on)}).join('')+(ACCS.every(k=>!own('a:'+k))?'<div style="grid-column:1/-1"><small>Belum punya aksesori. Coba Gacha.</small></div>':'')+'</div>';
 }
 P(`<div class=hd><b>Teman · ${frNm()}</b><div class=tabs><button onclick="gacha()">🎰 Gacha</button></div></div>
 <div class=fx><div class=pvw><div class=dt style="min-height:0"><canvas id=frp width=40 height=42 style="width:100%;image-rendering:pixelated;display:block;background:#e8dcc0;border:3px solid #3a2535;border-radius:8px"></canvas><small>${FRROLE[s.role]} · ${SEASONS[o].n}</small></div></div><div class="tabs vt">${tab('info','Info')}${tab('baju','👕 Baju')}${tab('topi','🎩 Topi')}${tab('rambut','💇 Rambut')}${tab('acc','✨ Aksesori')}</div><div class=gd>${body}</div></div>`);
 $('m').classList.add('wide');paintPV();
 const c=$('frp');if(c)render(c.getContext('2d'),{expr:'senang',pose:'berdiri',season:o,hat:cur,hair:F.h,hairStyle:F.s,acc,g,blink:false,gx:0,gy:0},0,false);
 const i=$('frn');if(i){i.value=s.name||'';let pv=i.value,mv2=0;i.onkeydown=e=>{e.stopPropagation();if(e.key==='Enter')frSaveName();if(/^(Arrow|Home|End)/.test(e.key))mv2=1};i.onkeyup=e=>e.stopPropagation();i.addEventListener('pointerdown',()=>{mv2=1});
  const fixEnd=()=>{const v=i.value;if(!mv2&&pv&&v.length===pv.length+1&&v.slice(1)===pv){i.value=pv+v[0]}try{const n=i.value.length;if(!mv2&&document.activeElement===i)i.setSelectionRange(n,n)}catch(e){}pv=i.value;mv2=0};i.addEventListener('input',fixEnd);i.addEventListener('compositionend',fixEnd)}}
$('ft').onclick=()=>{FRC=0;frPanel()};
